// =============================================================================
// ROLES TABLE
// Stable organizational functions separated from the agents that currently fill them. Maps to pro:Role.
// =============================================================================

// Role represents a row in the Roles table
type Role struct {
	RoleId string `json:"role_id"` // Stored logical identifier for one Roles row.
	Name *string `json:"name"` // Human-readable calculated display alias for the Roles row.
	Label *string `json:"label"` // Human-readable role label.
	Organization *string `json:"organization"` // Organization that owns the role.
	CurrentAgent *string `json:"current_agent"` // Current agent filling the role; history is retained in RoleAssignments.
	CurrentAgentKind *string `json:"current_agent_kind"` // Agent category of the current role filler.
	Responsibility *string `json:"responsibility"` // Accountability and responsibility assigned to the role.
	ActiveAssignmentCount *float64 `json:"active_assignment_count"` // Total number of assignment rows ever recorded against this role.
	CurrentlyCoveredAssignmentCount *float64 `json:"currently_covered_assignment_count"` // Number of assignment rows for this role that are in force right now.
	HasNoCurrentHolder *bool `json:"has_no_current_holder"` // TRUE when no assignment currently covers this role — the role is uncovered.
	CountOfAwaitedDecisions *int `json:"count_of_awaited_decisions"` // How many change requests name this role as the deciding authority.
	CurrentAssignment *string `json:"current_assignment"` // The RoleAssignments id of the assignment by which this role is currently held. Deliberately a raw identifier, not a relationship: RoleAssignments already points at Roles, so an FK back would make the two mutually dependent and this rulebook must stay acyclic.
	CurrentAssignmentValidFrom *string `json:"current_assignment_valid_from"` // Start of the currently-in-force assignment for this role.
	IsNonHumanHeld *bool `json:"is_non_human_held"` // TRUE when the role's current agent is an AI agent or automated pipeline.
	IsUngovernedNonHumanRole *bool `json:"is_ungoverned_non_human_role"` // TRUE when a role is pointed at a non-human agent but has no assignment row granting it.
	DepartedAssignmentCount *float64 `json:"departed_assignment_count"` // How many assignments to this role have ended.
	HasLostAHolder *bool `json:"has_lost_a_holder"` // Whether anyone has ever departed this role.
	IsVacatedRole *bool `json:"is_vacated_role"` // A role somebody departed and that nobody currently covers.
	UngroundedBoundaryCount *float64 `json:"ungrounded_boundary_count"` // How many boundaries constrain this role on lapsed authority.
	IsGovernedByLapsedAuthority *bool `json:"is_governed_by_lapsed_authority"` // TRUE when at least one constraint on this role rests on knowledge that is no longer valid.
	UnescalatedRefusalCount *float64 `json:"unescalated_refusal_count"` // How many refusals this role should have been told about and was not.
	UnauthorizedEnforcementAssignmentCount *float64 `json:"unauthorized_enforcement_assignment_count"` // How many current assignments of this role are unauthorized enforcement assignments.
	IsUngovernedEnforcementRole *bool `json:"is_ungoverned_enforcement_role"` // TRUE when a role that enforces controls on others is held with no recorded authorization.
	SemanticTypeIri *string `json:"semantic_type_iri"` // Exact semantic type IRI for the role.
	ErbErrors map[string]string `json:"_erb_errors,omitempty"`
	erbAggregates map[string]Value
}

// CalcName computes the Name calculated field
// Human-readable calculated display alias for the Roles row.
// Formula: ={{Label}}
func (tc *Role) CalcName() *string {
	return toStringPtr(vStr(tc.Label))
}

// CalcHasNoCurrentHolder computes the HasNoCurrentHolder calculated field
// TRUE when no assignment currently covers this role — the role is uncovered.
// Formula: ={{CurrentlyCoveredAssignmentCount}} = 0
func (tc *Role) CalcHasNoCurrentHolder() *bool {
	return toBoolPtr(erbEq(vNum(tc.CurrentlyCoveredAssignmentCount), vI(0)))
}

// CalcIsNonHumanHeld computes the IsNonHumanHeld calculated field
// TRUE when the role's current agent is an AI agent or automated pipeline.
// Formula: =NOT({{CurrentAgentKind}} = "Human")
func (tc *Role) CalcIsNonHumanHeld() *bool {
	return toBoolPtr(erbNot(erbBool3(erbEq(vStr(tc.CurrentAgentKind), vS("Human")))))
}

// CalcIsUngovernedNonHumanRole computes the IsUngovernedNonHumanRole calculated field
// TRUE when a role is pointed at a non-human agent but has no assignment row granting it.
// Formula: =AND({{IsNonHumanHeld}}, {{HasNoCurrentHolder}})
func (tc *Role) CalcIsUngovernedNonHumanRole() *bool {
	return toBoolPtr(erbAnd(erbBool3(vBool(tc.IsNonHumanHeld)), erbBool3(vBool(tc.HasNoCurrentHolder))))
}

// CalcHasLostAHolder computes the HasLostAHolder calculated field
// Whether anyone has ever departed this role.
// Formula: ={{DepartedAssignmentCount}} > 0
func (tc *Role) CalcHasLostAHolder() *bool {
	return toBoolPtr(erbCmp(vNum(tc.DepartedAssignmentCount), ">", vI(0)))
}

// CalcIsVacatedRole computes the IsVacatedRole calculated field
// A role somebody departed and that nobody currently covers.
// Formula: =AND({{HasLostAHolder}}, {{HasNoCurrentHolder}})
func (tc *Role) CalcIsVacatedRole() *bool {
	return toBoolPtr(erbAnd(erbBool3(vBool(tc.HasLostAHolder)), erbBool3(vBool(tc.HasNoCurrentHolder))))
}

// CalcIsGovernedByLapsedAuthority computes the IsGovernedByLapsedAuthority calculated field
// TRUE when at least one constraint on this role rests on knowledge that is no longer valid.
// Formula: =({{UngroundedBoundaryCount}} > 0)
func (tc *Role) CalcIsGovernedByLapsedAuthority() *bool {
	return toBoolPtr(erbCmp(vNum(tc.UngroundedBoundaryCount), ">", vI(0)))
}

// CalcIsUngovernedEnforcementRole computes the IsUngovernedEnforcementRole calculated field
// TRUE when a role that enforces controls on others is held with no recorded authorization.
// Formula: =({{UnauthorizedEnforcementAssignmentCount}} > 0)
func (tc *Role) CalcIsUngovernedEnforcementRole() *bool {
	return toBoolPtr(erbCmp(vNum(tc.UnauthorizedEnforcementAssignmentCount), ">", vI(0)))
}

// erbComputeCalculations computes every calculated field of the row in dependency order.
func (tc *Role) erbComputeCalculations() {
	// Level 1
	calcGuard(tc, "name", func() { tc.Name = tc.CalcName() })
	calcGuard(tc, "has_no_current_holder", func() { tc.HasNoCurrentHolder = tc.CalcHasNoCurrentHolder() })
	calcGuard(tc, "is_non_human_held", func() { tc.IsNonHumanHeld = tc.CalcIsNonHumanHeld() })
	calcGuard(tc, "has_lost_a_holder", func() { tc.HasLostAHolder = tc.CalcHasLostAHolder() })
	calcGuard(tc, "is_governed_by_lapsed_authority", func() { tc.IsGovernedByLapsedAuthority = tc.CalcIsGovernedByLapsedAuthority() })
	calcGuard(tc, "is_ungoverned_enforcement_role", func() { tc.IsUngovernedEnforcementRole = tc.CalcIsUngovernedEnforcementRole() })
	// Level 2
	calcGuard(tc, "is_ungoverned_non_human_role", func() { tc.IsUngovernedNonHumanRole = tc.CalcIsUngovernedNonHumanRole() })
	calcGuard(tc, "is_vacated_role", func() { tc.IsVacatedRole = tc.CalcIsVacatedRole() })
}

// ComputeAll computes every calculated field from the row's current inputs.
func (tc *Role) ComputeAll() *Role {
	tc.erbComputeCalculations()
	return tc
}

