	calcGuard(tc, "is_in_cadence_breach", func() { tc.IsInCadenceBreach = tc.CalcIsInCadenceBreach() })
	calcGuard(tc, "has_decision_in_flight", func() { tc.HasDecisionInFlight = tc.CalcHasDecisionInFlight() })
	calcGuard(tc, "still_owns_valid_knowledge", func() { tc.StillOwnsValidKnowledge = tc.CalcStillOwnsValidKnowledge() })
	calcGuard(tc, "is_still_referenced", func() { tc.IsStillReferenced = tc.CalcIsStillReferenced() })
	calcGuard(tc, "control_taxonomy_is_incomplete", func() { tc.ControlTaxonomyIsIncomplete = tc.CalcControlTaxonomyIsIncomplete() })
	calcGuard(tc, "has_approved_change_request", func() { tc.HasApprovedChangeRequest = tc.CalcHasApprovedChangeRequest() })
	calcGuard(tc, "has_unresolved_mining_drift", func() { tc.HasUnresolvedMiningDrift = tc.CalcHasUnresolvedMiningDrift() })
	// Level 2
	calcGuard(tc, "is_unstewarded", func() { tc.IsUnstewarded = tc.CalcIsUnstewarded() })
	calcGuard(tc, "is_live_with_blocking_gap", func() { tc.IsLiveWithBlockingGap = tc.CalcIsLiveWithBlockingGap() })
