	calcGuard(tc, "was_modified_since_last_review", func() { tc.WasModifiedSinceLastReview = tc.CalcWasModifiedSinceLastReview() })
	calcGuard(tc, "rests_on_compound_fragile_knowledge", func() { tc.RestsOnCompoundFragileKnowledge = tc.CalcRestsOnCompoundFragileKnowledge() })
	calcGuard(tc, "knowledge_base_is_concentrated", func() { tc.KnowledgeBaseIsConcentrated = tc.CalcKnowledgeBaseIsConcentrated() })
	calcGuard(tc, "feeds_unapproved_knowledge_to_machines", func() { tc.FeedsUnapprovedKnowledgeToMachines = tc.CalcFeedsUnapprovedKnowledgeToMachines() })
	calcGuard(tc, "ai_boundary_is_unevidenced", func() { tc.AiBoundaryIsUnevidenced = tc.CalcAiBoundaryIsUnevidenced() })
	calcGuard(tc, "is_live_with_unrehearsed_control", func() { tc.IsLiveWithUnrehearsedControl = tc.CalcIsLiveWithUnrehearsedControl() })
	calcGuard(tc, "is_unremediated_cadence_breach", func() { tc.IsUnremediatedCadenceBreach = tc.CalcIsUnremediatedCadenceBreach() })
	calcGuard(tc, "is_managed_cadence_breach", func() { tc.IsManagedCadenceBreach = tc.CalcIsManagedCadenceBreach() })
	calcGuard(tc, "governance_is_silent", func() { tc.GovernanceIsSilent = tc.CalcGovernanceIsSilent() })
	calcGuard(tc, "is_held_unfit_by_landed_decisions", func() { tc.IsHeldUnfitByLandedDecisions = tc.CalcIsHeldUnfitByLandedDecisions() })
	// Level 3
	calcGuard(tc, "is_live_and_unstewarded", func() { tc.IsLiveAndUnstewarded = tc.CalcIsLiveAndUnstewarded() })
