// =============================================================================
// STEPS TABLE
// Version-scoped units of work. Atomic steps map to pplan:Step; composite steps map to pplan:MultiStep. The specification is never conflated with execution.
// =============================================================================

// Step represents a row in the Steps table
type Step struct {
	StepId string `json:"step_id"` // Stored logical identifier for one Steps row.
	Name *string `json:"name"` // Human-readable calculated display alias for the Steps row.
	ProcedureVersion *string `json:"procedure_version"` // Procedure version containing the step; maps to pko:hasStep/pplan:isStepOfPlan.
	StepNumber *string `json:"step_number"` // Stable sequence label; maps to pko:stepNumber.
	Title *string `json:"title"` // Human-readable step title.
	StepKind *string `json:"step_kind"` // Atomic or MultiStep.
	AssignedRole *string `json:"assigned_role"` // Role responsible for the step.
	AssignedRoleLabel *string `json:"assigned_role_label"` // Resolved role label.
	AssignedAgentKind *string `json:"assigned_agent_kind"` // Current role-filler category.
	Instruction *string `json:"instruction"` // Normative step instruction.
	ExpectedDurationMinutes *int `json:"expected_duration_minutes"` // Expected duration represented as an OWL-Time duration in semantic projections.
	ExpertiseLevel *string `json:"expertise_level"` // PKO expertise level: Junior, Senior, Expert, or Master.
	RequiresHumanConfirmation *bool `json:"requires_human_confirmation"` // TRUE when a human must confirm the step; maps to pko:wasConfirmedBy at execution.
	BlockingRequirementCount *float64 `json:"blocking_requirement_count"` // How many blocking requirements the specification attaches to this step.
	StaleBindingCount *float64 `json:"stale_binding_count"` // How many operational bindings for this step are currently outside their freshness SLA.
	AuthoritativeStaleCount *float64 `json:"authoritative_stale_count"` // How many authoritative bindings for this step are currently stale.
	AvailableExceptionCount *float64 `json:"available_exception_count"` // How many active exceptions the specification defines for this step.
	DeclaredVerificationCount *float64 `json:"declared_verification_count"` // How many verifications the specification declares for this step.
	IsPreparationStep *bool `json:"is_preparation_step"` // TRUE for steps whose assigned role produces the work product rather than reviewing it.
	IsApprovalStep *bool `json:"is_approval_step"` // TRUE for steps whose assigned role is an approval authority.
	StaleAuthoritativeBindingCount *float64 `json:"stale_authoritative_binding_count"` // Number of authoritative bindings for this step that are past their freshness SLA.
	InputsAreFresh *bool `json:"inputs_are_fresh"` // TRUE when no authoritative binding for this step is stale.
	IsSoftwareAssigned *bool `json:"is_software_assigned"` // TRUE when this step is specified to be performed by software rather than a person.
	IsHumanApprovalGate *bool `json:"is_human_approval_gate"` // TRUE for the steps that exist specifically to place a human commitment between drafting and delivery.
	GateHeldByHuman *bool `json:"gate_held_by_human"` // TRUE when a designated approval gate is in fact assigned to a human role.
	BindingBoundaryCount *float64 `json:"binding_boundary_count"` // Number of authority boundaries currently binding at this step.
	AssignedRoleIsUngoverned *bool `json:"assigned_role_is_ungoverned"` // Whether this step's assigned role is a non-human role with no governing assignment.
	UnusableBindingCount *float64 `json:"unusable_binding_count"` // Number of bindings at this step that are unapproved or stale.
	AllSourcesUsable *bool `json:"all_sources_usable"` // TRUE when every binding at this step is an approved, fresh source.
	ControlKind *string `json:"control_kind"` // What kind of control this step is: Preparation, Approval, LegalReview, Verification, Extraction, Publication, Retrospective, or None. That policy-04 is a legal review is a property OF policy-04, not of a formula that happens to name it; storing it as data makes downstream predicates portable to procedures that do not exist yet.
	UnwarrantedBoundaryCount *float64 `json:"unwarranted_boundary_count"` // How many boundaries governing this step are being enforced without a valid ratifying claim.
	IsGovernedByUnwarrantedBoundary *bool `json:"is_governed_by_unwarranted_boundary"` // Whether this step's constraints on machine authority rest on a claim that is no longer valid.
	SoftwareExecutionCount *float64 `json:"software_execution_count"` // How many times a software agent has actually executed this step.
	HasBeenApproachedBySoftware *bool `json:"has_been_approached_by_software"` // Whether any software agent has ever executed this step.
	IsUnexercisedHumanGate *bool `json:"is_unexercised_human_gate"` // A human-only approval gate that no software agent has ever attempted — the control is asserted, not demonstrated.
	IsDemonstratedHumanGate *bool `json:"is_demonstrated_human_gate"` // A human gate that software has actually reached and that a human nevertheless held.
	UnexercisedGateVersionKey *string `json:"unexercised_gate_version_key"` // Composite-key echo: this step's procedure version when the step is an unexercised human gate, blank otherwise.
	HasDeclaredControlKind *bool `json:"has_declared_control_kind"` // Whether this step declares what kind of control it is.
	UndeclaredControlVersionKey *string `json:"undeclared_control_version_key"` // Composite-key echo: this step's procedure version when the step has no declared control kind, blank otherwise.
	ApprovalStepIsSoftwareAssigned *bool `json:"approval_step_is_software_assigned"` // An approval-kind step whose assigned role is currently held by an AI agent or automated pipeline.
	UnwitnessedBlockingCount *float64 `json:"unwitnessed_blocking_count"` // How many blocking controls bound to this step have no computed witness.
	ReachableStepCount *int `json:"reachable_step_count"` // Number of steps this step can lead to through one or more transitions, including itself when it lies on a rework loop.
	ReachedFromStepCount *int `json:"reached_from_step_count"` // Number of steps that can lead to this step through one or more transitions, including itself when it lies on a rework loop.
	SelfReachCount *int `json:"self_reach_count"` // 1 when the closure contains the pair (this step, this step), i.e. some path of one or more transitions returns to this step; otherwise 0.
	IsOnReworkLoop *bool `json:"is_on_rework_loop"` // The procedure can send work back to this step after it has run: the step lies on a cycle of the step graph.
	IsBlockingControlOnReworkLoop *bool `json:"is_blocking_control_on_rework_loop"` // A step carrying at least one blocking requirement can be re-entered, so that control must hold on every pass, not only the first.
	IncomingTransitionCount *int `json:"incoming_transition_count"` // Number of transitions, of any kind, that lead into this step.
	IsEntryStep *bool `json:"is_entry_step"` // No transition leads into this step: the procedure version starts here.
	EntryStepKey *string `json:"entry_step_key"` // Composite-key echo: this step's id when it is its procedure version's entry step, blank otherwise.
	VersionEntryStepId *string `json:"version_entry_step_id"` // The entry step of this step's procedure version.
	GateFreeReachFromEntryCount *int `json:"gate_free_reach_from_entry_count"` // 1 when some route of one or more gate-free transitions leads from the procedure version's entry step to this step; otherwise 0.
	IsReachableFromEntryWithoutHumanGate *bool `json:"is_reachable_from_entry_without_human_gate"` // Work can arrive at this step from the start of the procedure without passing any human approval gate.
	IsGateBypassedPublication *bool `json:"is_gate_bypassed_publication"` // A publication step the procedure can reach without human sign-off: the approval gate is structurally bypassable.
	SemanticTypeIri *string `json:"semantic_type_iri"` // Exact P-Plan class IRI.
	ErbErrors map[string]string `json:"_erb_errors,omitempty"`
	erbAggregates map[string]Value
}

// CalcName computes the Name calculated field
// Human-readable calculated display alias for the Steps row.
// Formula: ={{StepNumber}} & ". " & {{Title}}
func (tc *Step) CalcName() *string {
	return toStringPtr(erbConcat(erbText(vStr(tc.StepNumber)), vS(". "), erbText(vStr(tc.Title))))
}

// CalcIsPreparationStep computes the IsPreparationStep calculated field
// TRUE for steps whose assigned role produces the work product rather than reviewing it.
// Formula: =OR({{AssignedRole}} = "finance-analyst", {{AssignedRole}} = "variance-review-agent")
func (tc *Step) CalcIsPreparationStep() *bool {
	return toBoolPtr(erbOr(erbBool3(erbEq(erbNullif(vStr(tc.AssignedRole)), vS("finance-analyst"))), erbBool3(erbEq(erbNullif(vStr(tc.AssignedRole)), vS("variance-review-agent")))))
}

// CalcIsApprovalStep computes the IsApprovalStep calculated field
// TRUE for steps whose assigned role is an approval authority.
// Formula: =OR({{AssignedRole}} = "controller", {{AssignedRole}} = "cfo")
func (tc *Step) CalcIsApprovalStep() *bool {
	return toBoolPtr(erbOr(erbBool3(erbEq(erbNullif(vStr(tc.AssignedRole)), vS("controller"))), erbBool3(erbEq(erbNullif(vStr(tc.AssignedRole)), vS("cfo")))))
}

// CalcInputsAreFresh computes the InputsAreFresh calculated field
// TRUE when no authoritative binding for this step is stale.
// Formula: ={{StaleAuthoritativeBindingCount}} = 0
func (tc *Step) CalcInputsAreFresh() *bool {
	return toBoolPtr(erbEq(vNum(tc.StaleAuthoritativeBindingCount), vI(0)))
}

// CalcIsSoftwareAssigned computes the IsSoftwareAssigned calculated field
// TRUE when this step is specified to be performed by software rather than a person.
// Formula: =OR({{AssignedAgentKind}} = "AIAgent", {{AssignedAgentKind}} = "AutomatedPipeline")
func (tc *Step) CalcIsSoftwareAssigned() *bool {
	return toBoolPtr(erbOr(erbBool3(erbEq(vStr(tc.AssignedAgentKind), vS("AIAgent"))), erbBool3(erbEq(vStr(tc.AssignedAgentKind), vS("AutomatedPipeline")))))
}

// CalcIsHumanApprovalGate computes the IsHumanApprovalGate calculated field
// TRUE for the steps that exist specifically to place a human commitment between drafting and delivery.
// Formula: =AND(NOT({{IsSoftwareAssigned}}), OR({{StepId}} = "policy-05", {{StepId}} = "close-06"))
func (tc *Step) CalcIsHumanApprovalGate() *bool {
	return toBoolPtr(erbAnd(erbBool3(erbNot(erbBool3(vBool(tc.IsSoftwareAssigned)))), erbBool3(erbOr(erbBool3(erbEq(erbNullif(vStrPlain(tc.StepId)), vS("policy-05"))), erbBool3(erbEq(erbNullif(vStrPlain(tc.StepId)), vS("close-06")))))))
}

// CalcGateHeldByHuman computes the GateHeldByHuman calculated field
// TRUE when a designated approval gate is in fact assigned to a human role.
// Formula: =AND({{IsHumanApprovalGate}}, {{AssignedAgentKind}} = "Human")
func (tc *Step) CalcGateHeldByHuman() *bool {
	return toBoolPtr(erbAnd(erbBool3(vBool(tc.IsHumanApprovalGate)), erbBool3(erbEq(vStr(tc.AssignedAgentKind), vS("Human")))))
}

// CalcAllSourcesUsable computes the AllSourcesUsable calculated field
// TRUE when every binding at this step is an approved, fresh source.
// Formula: ={{UnusableBindingCount}} = 0
func (tc *Step) CalcAllSourcesUsable() *bool {
	return toBoolPtr(erbEq(vNum(tc.UnusableBindingCount), vI(0)))
}

// CalcIsGovernedByUnwarrantedBoundary computes the IsGovernedByUnwarrantedBoundary calculated field
// Whether this step's constraints on machine authority rest on a claim that is no longer valid.
// Formula: ={{UnwarrantedBoundaryCount}} > 0
func (tc *Step) CalcIsGovernedByUnwarrantedBoundary() *bool {
	return toBoolPtr(erbCmp(vNum(tc.UnwarrantedBoundaryCount), ">", vI(0)))
}

// CalcHasBeenApproachedBySoftware computes the HasBeenApproachedBySoftware calculated field
// Whether any software agent has ever executed this step.
// Formula: ={{SoftwareExecutionCount}} > 0
func (tc *Step) CalcHasBeenApproachedBySoftware() *bool {
	return toBoolPtr(erbCmp(vNum(tc.SoftwareExecutionCount), ">", vI(0)))
}

// CalcIsUnexercisedHumanGate computes the IsUnexercisedHumanGate calculated field
// A human-only approval gate that no software agent has ever attempted — the control is asserted, not demonstrated.
// Formula: =AND({{IsHumanApprovalGate}}, NOT({{HasBeenApproachedBySoftware}}))
func (tc *Step) CalcIsUnexercisedHumanGate() *bool {
	return toBoolPtr(erbAnd(erbBool3(vBool(tc.IsHumanApprovalGate)), erbBool3(erbNot(erbBool3(vBool(tc.HasBeenApproachedBySoftware))))))
}

// CalcIsDemonstratedHumanGate computes the IsDemonstratedHumanGate calculated field
// A human gate that software has actually reached and that a human nevertheless held.
// Formula: =AND({{IsHumanApprovalGate}}, {{HasBeenApproachedBySoftware}}, {{GateHeldByHuman}})
func (tc *Step) CalcIsDemonstratedHumanGate() *bool {
	return toBoolPtr(erbAnd(erbBool3(vBool(tc.IsHumanApprovalGate)), erbBool3(vBool(tc.HasBeenApproachedBySoftware)), erbBool3(vBool(tc.GateHeldByHuman))))
}

// CalcUnexercisedGateVersionKey computes the UnexercisedGateVersionKey calculated field
// Composite-key echo: this step's procedure version when the step is an unexercised human gate, blank otherwise.
// Formula: =IF({{IsUnexercisedHumanGate}}, {{ProcedureVersion}}, "")
func (tc *Step) CalcUnexercisedGateVersionKey() *string {
	return toStringPtr(erbIf(erbBool3(vBool(tc.IsUnexercisedHumanGate)), func() Value { return vStr(tc.ProcedureVersion) }, func() Value { return vS("") }))
}

// CalcHasDeclaredControlKind computes the HasDeclaredControlKind calculated field
// Whether this step declares what kind of control it is.
// Formula: ={{ControlKind}} <> ""
func (tc *Step) CalcHasDeclaredControlKind() *bool {
	return toBoolPtr(erbIsNotBlank(vStr(tc.ControlKind)))
}

// CalcUndeclaredControlVersionKey computes the UndeclaredControlVersionKey calculated field
// Composite-key echo: this step's procedure version when the step has no declared control kind, blank otherwise.
// Formula: =IF({{HasDeclaredControlKind}}, "", {{ProcedureVersion}})
func (tc *Step) CalcUndeclaredControlVersionKey() *string {
	return toStringPtr(erbIf(erbBool3(vBool(tc.HasDeclaredControlKind)), func() Value { return vS("") }, func() Value { return vStr(tc.ProcedureVersion) }))
}

// CalcApprovalStepIsSoftwareAssigned computes the ApprovalStepIsSoftwareAssigned calculated field
// An approval-kind step whose assigned role is currently held by an AI agent or automated pipeline.
// Formula: =AND({{ControlKind}} = "Approval", {{IsSoftwareAssigned}})
func (tc *Step) CalcApprovalStepIsSoftwareAssigned() *bool {
	return toBoolPtr(erbAnd(erbBool3(erbEq(erbNullif(vStr(tc.ControlKind)), vS("Approval"))), erbBool3(vBool(tc.IsSoftwareAssigned))))
}

// CalcIsOnReworkLoop computes the IsOnReworkLoop calculated field
// The procedure can send work back to this step after it has run: the step lies on a cycle of the step graph.
// Formula: ={{SelfReachCount}} > 0
func (tc *Step) CalcIsOnReworkLoop() *bool {
	return toBoolPtr(erbCmp(vInt(tc.SelfReachCount), ">", vI(0)))
}

// CalcIsBlockingControlOnReworkLoop computes the IsBlockingControlOnReworkLoop calculated field
// A step carrying at least one blocking requirement can be re-entered, so that control must hold on every pass, not only the first.
// Formula: =AND({{IsOnReworkLoop}}, {{BlockingRequirementCount}} > 0)
func (tc *Step) CalcIsBlockingControlOnReworkLoop() *bool {
	return toBoolPtr(erbAnd(erbBool3(vBool(tc.IsOnReworkLoop)), erbBool3(erbCmp(vNum(tc.BlockingRequirementCount), ">", vI(0)))))
}

// CalcIsEntryStep computes the IsEntryStep calculated field
// No transition leads into this step: the procedure version starts here.
// Formula: ={{IncomingTransitionCount}} = 0
func (tc *Step) CalcIsEntryStep() *bool {
	return toBoolPtr(erbEq(vInt(tc.IncomingTransitionCount), vI(0)))
}

// CalcEntryStepKey computes the EntryStepKey calculated field
// Composite-key echo: this step's id when it is its procedure version's entry step, blank otherwise.
// Formula: =IF({{IsEntryStep}}, {{StepId}}, "")
func (tc *Step) CalcEntryStepKey() *string {
	return toStringPtr(erbIf(erbBool3(vBool(tc.IsEntryStep)), func() Value { return vStrPlain(tc.StepId) }, func() Value { return vS("") }))
}

// CalcIsReachableFromEntryWithoutHumanGate computes the IsReachableFromEntryWithoutHumanGate calculated field
// Work can arrive at this step from the start of the procedure without passing any human approval gate.
// Formula: ={{GateFreeReachFromEntryCount}} > 0
func (tc *Step) CalcIsReachableFromEntryWithoutHumanGate() *bool {
	return toBoolPtr(erbCmp(vInt(tc.GateFreeReachFromEntryCount), ">", vI(0)))
}

// CalcIsGateBypassedPublication computes the IsGateBypassedPublication calculated field
// A publication step the procedure can reach without human sign-off: the approval gate is structurally bypassable.
// Formula: =AND({{ControlKind}} = "Publication", {{IsReachableFromEntryWithoutHumanGate}})
func (tc *Step) CalcIsGateBypassedPublication() *bool {
	return toBoolPtr(erbAnd(erbBool3(erbEq(erbNullif(vStr(tc.ControlKind)), vS("Publication"))), erbBool3(vBool(tc.IsReachableFromEntryWithoutHumanGate))))
}

// erbComputeCalculations computes every calculated field of the row in dependency order.
func (tc *Step) erbComputeCalculations() {
	// Level 1
	calcGuard(tc, "name", func() { tc.Name = tc.CalcName() })
	calcGuard(tc, "is_preparation_step", func() { tc.IsPreparationStep = tc.CalcIsPreparationStep() })
	calcGuard(tc, "is_approval_step", func() { tc.IsApprovalStep = tc.CalcIsApprovalStep() })
	calcGuard(tc, "inputs_are_fresh", func() { tc.InputsAreFresh = tc.CalcInputsAreFresh() })
	calcGuard(tc, "is_software_assigned", func() { tc.IsSoftwareAssigned = tc.CalcIsSoftwareAssigned() })
	calcGuard(tc, "all_sources_usable", func() { tc.AllSourcesUsable = tc.CalcAllSourcesUsable() })
	calcGuard(tc, "is_governed_by_unwarranted_boundary", func() { tc.IsGovernedByUnwarrantedBoundary = tc.CalcIsGovernedByUnwarrantedBoundary() })
	calcGuard(tc, "has_been_approached_by_software", func() { tc.HasBeenApproachedBySoftware = tc.CalcHasBeenApproachedBySoftware() })
	calcGuard(tc, "has_declared_control_kind", func() { tc.HasDeclaredControlKind = tc.CalcHasDeclaredControlKind() })
	calcGuard(tc, "is_on_rework_loop", func() { tc.IsOnReworkLoop = tc.CalcIsOnReworkLoop() })
	calcGuard(tc, "is_entry_step", func() { tc.IsEntryStep = tc.CalcIsEntryStep() })
	calcGuard(tc, "is_reachable_from_entry_without_human_gate", func() { tc.IsReachableFromEntryWithoutHumanGate = tc.CalcIsReachableFromEntryWithoutHumanGate() })
	// Level 2
	calcGuard(tc, "is_human_approval_gate", func() { tc.IsHumanApprovalGate = tc.CalcIsHumanApprovalGate() })
	calcGuard(tc, "undeclared_control_version_key", func() { tc.UndeclaredControlVersionKey = tc.CalcUndeclaredControlVersionKey() })
	calcGuard(tc, "approval_step_is_software_assigned", func() { tc.ApprovalStepIsSoftwareAssigned = tc.CalcApprovalStepIsSoftwareAssigned() })
	calcGuard(tc, "is_blocking_control_on_rework_loop", func() { tc.IsBlockingControlOnReworkLoop = tc.CalcIsBlockingControlOnReworkLoop() })
	calcGuard(tc, "entry_step_key", func() { tc.EntryStepKey = tc.CalcEntryStepKey() })
	calcGuard(tc, "is_gate_bypassed_publication", func() { tc.IsGateBypassedPublication = tc.CalcIsGateBypassedPublication() })
	// Level 3
	calcGuard(tc, "gate_held_by_human", func() { tc.GateHeldByHuman = tc.CalcGateHeldByHuman() })
	calcGuard(tc, "is_unexercised_human_gate", func() { tc.IsUnexercisedHumanGate = tc.CalcIsUnexercisedHumanGate() })
	// Level 4
	calcGuard(tc, "is_demonstrated_human_gate", func() { tc.IsDemonstratedHumanGate = tc.CalcIsDemonstratedHumanGate() })
	calcGuard(tc, "unexercised_gate_version_key", func() { tc.UnexercisedGateVersionKey = tc.CalcUnexercisedGateVersionKey() })
}

// ComputeAll computes every calculated field from the row's current inputs.
func (tc *Step) ComputeAll() *Step {
	tc.erbComputeCalculations()
	return tc
}

