// =============================================================================
// STEPTRANSITIONS TABLE
// Directed control-flow edges represented as first-class pko:Transition instances with fromStep/toStep and next/alternative/fallback semantics.
// =============================================================================

// StepTransition represents a row in the StepTransitions table
type StepTransition struct {
	StepTransitionId string `json:"step_transition_id"` // Stored logical identifier for one StepTransitions row.
	Name *string `json:"name"` // Human-readable calculated display alias for the StepTransitions row.
	ProcedureVersion *string `json:"procedure_version"` // Procedure version whose control flow owns the transition.
	FromStep *string `json:"from_step"` // Source step; maps to pko:fromStep.
	ToStep *string `json:"to_step"` // Destination step; maps to pko:toStep.
	TransitionKind *string `json:"transition_kind"` // Next, Alternative, or Fallback.
	Condition *string `json:"condition"` // Condition under which the edge is taken.
	Priority *int `json:"priority"` // Evaluation priority when several outgoing edges exist.
	IsRecoveryPath *bool `json:"is_recovery_path"` // TRUE when this transition is a non-default path taken because something went wrong.
	CountOfFromStepExecutions *int `json:"count_of_from_step_executions"` // How many times the step this transition leaves from has actually been executed.
	CountOfToStepExecutions *int `json:"count_of_to_step_executions"` // How many times the step this transition arrives at has actually been executed.
	HasReachableOrigin *bool `json:"has_reachable_origin"` // TRUE when the origin step of this transition has been executed at least once.
	HasReachableTarget *bool `json:"has_reachable_target"` // TRUE when the destination step of this transition has been executed at least once.
	IsNeverExercised *bool `json:"is_never_exercised"` // TRUE when at least one end of this transition has never appeared in any step execution.
	IsUntestedRecoveryPath *bool `json:"is_untested_recovery_path"` // TRUE for a Fallback or Alternative transition whose endpoints show no execution evidence.
	CountOfObservedTraversals *int `json:"count_of_observed_traversals"` // How many times this exact transition has actually been traversed.
	HasBeenTraversed *bool `json:"has_been_traversed"` // TRUE when this transition has been walked at least once.
	IsUnwalkedRecoveryPath *bool `json:"is_unwalked_recovery_path"` // TRUE for a Fallback/Alternative transition with zero recorded traversals.
	TargetBlockingRequirementCount *float64 `json:"target_blocking_requirement_count"` // How many blocking requirements are attached to the step this transition lands on.
	TargetCarriesBlockingControl *bool `json:"target_carries_blocking_control"` // Whether the destination step of this transition carries at least one blocking control.
	IsUnrehearsedControlEntry *bool `json:"is_unrehearsed_control_entry"` // A recovery path that has never been traversed and that leads into a step carrying a blocking control.
	UnrehearsedControlVersionKey *string `json:"unrehearsed_control_version_key"` // Composite-key echo: this transition's procedure version when it is an unrehearsed control entry, blank otherwise.
	LeadsToClosure any `json:"leads_to_closure"` // Transitive closure of the step graph (FromStep -> ToStep over every transition kind), materialized by each substrate as vw_step_transitions_closure: every (from, to) pair a procedure can lead to in one or more transitions. A step that lies on a cycle reaches itself.
	FromStepIsHumanApprovalGate *bool `json:"from_step_is_human_approval_gate"` // This transition leaves a human approval gate.
	ToStepIsHumanApprovalGate *bool `json:"to_step_is_human_approval_gate"` // This transition enters a human approval gate.
	AvoidsHumanApprovalGate *bool `json:"avoids_human_approval_gate"` // Neither end of this transition is a human approval gate, so a route made only of such transitions never passes a gate.
	LeadsWithoutHumanGateClosure any `json:"leads_without_human_gate_closure"` // Transitive closure of the step graph over only the transitions that avoid every human approval gate, materialized as vw_step_transitions_closure_where_avoids_human_approval_gate: every (from, to) pair a procedure can reach without passing a gate.
	SemanticTypeIri *string `json:"semantic_type_iri"` // Exact PKO class IRI.
	ErbErrors map[string]string `json:"_erb_errors,omitempty"`
	erbAggregates map[string]Value
}

// CalcName computes the Name calculated field
// Human-readable calculated display alias for the StepTransitions row.
// Formula: ={{FromStep}} & " -> " & {{ToStep}}
func (tc *StepTransition) CalcName() *string {
	return toStringPtr(erbConcat(erbText(vStr(tc.FromStep)), vS(" -> "), erbText(vStr(tc.ToStep))))
}

// CalcIsRecoveryPath computes the IsRecoveryPath calculated field
// TRUE when this transition is a non-default path taken because something went wrong.
// Formula: =OR({{TransitionKind}} = "Fallback", {{TransitionKind}} = "Alternative")
func (tc *StepTransition) CalcIsRecoveryPath() *bool {
	return toBoolPtr(erbOr(erbBool3(erbEq(erbNullif(vStr(tc.TransitionKind)), vS("Fallback"))), erbBool3(erbEq(erbNullif(vStr(tc.TransitionKind)), vS("Alternative")))))
}

// CalcHasReachableOrigin computes the HasReachableOrigin calculated field
// TRUE when the origin step of this transition has been executed at least once.
// Formula: ={{CountOfFromStepExecutions}} > 0
func (tc *StepTransition) CalcHasReachableOrigin() *bool {
	return toBoolPtr(erbCmp(vInt(tc.CountOfFromStepExecutions), ">", vI(0)))
}

// CalcHasReachableTarget computes the HasReachableTarget calculated field
// TRUE when the destination step of this transition has been executed at least once.
// Formula: ={{CountOfToStepExecutions}} > 0
func (tc *StepTransition) CalcHasReachableTarget() *bool {
	return toBoolPtr(erbCmp(vInt(tc.CountOfToStepExecutions), ">", vI(0)))
}

// CalcIsNeverExercised computes the IsNeverExercised calculated field
// TRUE when at least one end of this transition has never appeared in any step execution.
// Formula: =NOT(AND({{HasReachableOrigin}}, {{HasReachableTarget}}))
func (tc *StepTransition) CalcIsNeverExercised() *bool {
	return toBoolPtr(erbNot(erbBool3(erbAnd(erbBool3(vBool(tc.HasReachableOrigin)), erbBool3(vBool(tc.HasReachableTarget))))))
}

// CalcIsUntestedRecoveryPath computes the IsUntestedRecoveryPath calculated field
// TRUE for a Fallback or Alternative transition whose endpoints show no execution evidence.
// Formula: =AND({{IsRecoveryPath}}, {{IsNeverExercised}})
func (tc *StepTransition) CalcIsUntestedRecoveryPath() *bool {
	return toBoolPtr(erbAnd(erbBool3(vBool(tc.IsRecoveryPath)), erbBool3(vBool(tc.IsNeverExercised))))
}

// CalcHasBeenTraversed computes the HasBeenTraversed calculated field
// TRUE when this transition has been walked at least once.
// Formula: ={{CountOfObservedTraversals}} > 0
func (tc *StepTransition) CalcHasBeenTraversed() *bool {
	return toBoolPtr(erbCmp(vInt(tc.CountOfObservedTraversals), ">", vI(0)))
}

// CalcIsUnwalkedRecoveryPath computes the IsUnwalkedRecoveryPath calculated field
// TRUE for a Fallback/Alternative transition with zero recorded traversals.
// Formula: =AND({{IsRecoveryPath}}, NOT({{HasBeenTraversed}}))
func (tc *StepTransition) CalcIsUnwalkedRecoveryPath() *bool {
	return toBoolPtr(erbAnd(erbBool3(vBool(tc.IsRecoveryPath)), erbBool3(erbNot(erbBool3(vBool(tc.HasBeenTraversed))))))
}

// CalcTargetCarriesBlockingControl computes the TargetCarriesBlockingControl calculated field
// Whether the destination step of this transition carries at least one blocking control.
// Formula: ={{TargetBlockingRequirementCount}} > 0
func (tc *StepTransition) CalcTargetCarriesBlockingControl() *bool {
	return toBoolPtr(erbCmp(vNum(tc.TargetBlockingRequirementCount), ">", vI(0)))
}

// CalcIsUnrehearsedControlEntry computes the IsUnrehearsedControlEntry calculated field
// A recovery path that has never been traversed and that leads into a step carrying a blocking control.
// Formula: =AND({{IsUnwalkedRecoveryPath}}, {{TargetCarriesBlockingControl}})
func (tc *StepTransition) CalcIsUnrehearsedControlEntry() *bool {
	return toBoolPtr(erbAnd(erbBool3(vBool(tc.IsUnwalkedRecoveryPath)), erbBool3(vBool(tc.TargetCarriesBlockingControl))))
}

// CalcUnrehearsedControlVersionKey computes the UnrehearsedControlVersionKey calculated field
// Composite-key echo: this transition's procedure version when it is an unrehearsed control entry, blank otherwise.
// Formula: =IF({{IsUnrehearsedControlEntry}}, {{ProcedureVersion}}, "")
func (tc *StepTransition) CalcUnrehearsedControlVersionKey() *string {
	return toStringPtr(erbIf(erbBool3(vBool(tc.IsUnrehearsedControlEntry)), func() Value { return vStr(tc.ProcedureVersion) }, func() Value { return vS("") }))
}

// CalcAvoidsHumanApprovalGate computes the AvoidsHumanApprovalGate calculated field
// Neither end of this transition is a human approval gate, so a route made only of such transitions never passes a gate.
// Formula: =AND(NOT({{FromStepIsHumanApprovalGate}}), NOT({{ToStepIsHumanApprovalGate}}))
func (tc *StepTransition) CalcAvoidsHumanApprovalGate() *bool {
	return toBoolPtr(erbAnd(erbBool3(erbNot(erbBool3(vBool(tc.FromStepIsHumanApprovalGate)))), erbBool3(erbNot(erbBool3(vBool(tc.ToStepIsHumanApprovalGate))))))
}

// erbComputeCalculations computes every calculated field of the row in dependency order.
func (tc *StepTransition) erbComputeCalculations() {
	// Level 1
	calcGuard(tc, "name", func() { tc.Name = tc.CalcName() })
	calcGuard(tc, "is_recovery_path", func() { tc.IsRecoveryPath = tc.CalcIsRecoveryPath() })
	calcGuard(tc, "has_reachable_origin", func() { tc.HasReachableOrigin = tc.CalcHasReachableOrigin() })
	calcGuard(tc, "has_reachable_target", func() { tc.HasReachableTarget = tc.CalcHasReachableTarget() })
	calcGuard(tc, "has_been_traversed", func() { tc.HasBeenTraversed = tc.CalcHasBeenTraversed() })
	calcGuard(tc, "target_carries_blocking_control", func() { tc.TargetCarriesBlockingControl = tc.CalcTargetCarriesBlockingControl() })
	calcGuard(tc, "avoids_human_approval_gate", func() { tc.AvoidsHumanApprovalGate = tc.CalcAvoidsHumanApprovalGate() })
	// Level 2
	calcGuard(tc, "is_never_exercised", func() { tc.IsNeverExercised = tc.CalcIsNeverExercised() })
	calcGuard(tc, "is_unwalked_recovery_path", func() { tc.IsUnwalkedRecoveryPath = tc.CalcIsUnwalkedRecoveryPath() })
	// Level 3
	calcGuard(tc, "is_untested_recovery_path", func() { tc.IsUntestedRecoveryPath = tc.CalcIsUntestedRecoveryPath() })
	calcGuard(tc, "is_unrehearsed_control_entry", func() { tc.IsUnrehearsedControlEntry = tc.CalcIsUnrehearsedControlEntry() })
	// Level 4
	calcGuard(tc, "unrehearsed_control_version_key", func() { tc.UnrehearsedControlVersionKey = tc.CalcUnrehearsedControlVersionKey() })
}

// ComputeAll computes every calculated field from the row's current inputs.
