// =============================================================================
// REQUIREMENTS TABLE
// Normative requirements applied to procedures, steps, or transitions. Maps to pko:Requirement and pko:hasRequirement.
// =============================================================================

// Requirement represents a row in the Requirements table
type Requirement struct {
	RequirementId string `json:"requirement_id"` // Stored logical identifier for one Requirements row.
	Name *string `json:"name"` // Human-readable calculated display alias for the Requirements row.
	Label *string `json:"label"` // Requirement label.
	RequirementType *string `json:"requirement_type"` // Controlled requirement type; maps to pko:hasRequirementType.
	Statement *string `json:"statement"` // Normative requirement statement.
	Rationale *string `json:"rationale"` // Why the requirement exists.
	IsBlocking *bool `json:"is_blocking"` // TRUE when unsatisfied requirement blocks execution or approval.
	SatisfactionRecordCount *float64 `json:"satisfaction_record_count"` // How many times this requirement has ever been evaluated against an execution.
	StepBindingCount *float64 `json:"step_binding_count"` // How many steps the specification binds this requirement to.
	IsBoundToAnyStep *bool `json:"is_bound_to_any_step"` // TRUE when at least one step carries this requirement.
	HasEverBeenEvaluated *bool `json:"has_ever_been_evaluated"` // TRUE when this requirement has at least one satisfaction record in the model.
	NegativeOutcomeCount *float64 `json:"negative_outcome_count"` // How many times this requirement has ever produced a less-than-satisfied outcome.
	IsInoperativeControl *bool `json:"is_inoperative_control"` // TRUE for a blocking requirement that is attached to a step in the specification but has never once been evaluated on any execution.
	IsDecorativeControl *bool `json:"is_decorative_control"` // TRUE for a blocking requirement that is not attached to any step at all.
	HasComputedWitness *bool `json:"has_computed_witness"` // Whether a computed predicate in this rulebook evaluates this requirement, as opposed to it being satisfied by human assertion only.
	WitnessFieldName *string `json:"witness_field_name"` // The fully-qualified Table.Field of the predicate that computes this requirement, when one exists.
	HasEverProducedNegative *bool `json:"has_ever_produced_negative"` // TRUE when this requirement has at least once been scored as anything other than Satisfied.
	IsUnfalsifiedControl *bool `json:"is_unfalsified_control"` // TRUE for a blocking control that HAS been evaluated at least once and has never returned a negative result.
	ClaimsAWitnessField *bool `json:"claims_a_witness_field"` // TRUE when this requirement names a field it claims computes it.
	NamedWitnessFieldExists *bool `json:"named_witness_field_exists"` // TRUE when the field named in WitnessFieldName actually exists in the field catalog AND is a derived (calculated/lookup/aggregation) field.
	DerivedHasComputedWitness *bool `json:"derived_has_computed_witness"` // Whether this requirement genuinely has a computed witness, derived from the field catalog rather than asserted.
	WitnessClaimIsUnverified *bool `json:"witness_claim_is_unverified"` // TRUE when the hand-typed HasComputedWitness flag disagrees with what the field catalog says.
	IsUnwitnessedBlockingControl *bool `json:"is_unwitnessed_blocking_control"` // TRUE for a blocking control with no verified computed witness behind it.
	WitnessFireCount *float64 `json:"witness_fire_count"` // How many times this requirement's evaluation has returned a non-Satisfied result.
	WitnessHasNeverFired *bool `json:"witness_has_never_fired"` // TRUE for a requirement that has a computed witness which has never once returned a negative result.
	EvaluationSampleSize *float64 `json:"evaluation_sample_size"` // How many times this requirement has been evaluated at all.
	HasMeaningfulSample *bool `json:"has_meaningful_sample"` // TRUE when this requirement has been evaluated often enough that a clean record is informative.
	MinimumSampleForAssurance *int `json:"minimum_sample_for_assurance"` // The number of clean evaluations this control must accumulate before its silence counts as evidence.
	IsUntestedWitness *bool `json:"is_untested_witness"` // TRUE for a witness that has never fired and has not been exercised enough for that silence to mean anything.
	IsEvidencedHoldingControl *bool `json:"is_evidenced_holding_control"` // TRUE for a witness that has never fired across a sample large enough for that to constitute evidence.
	ControlAssuranceState *string `json:"control_assurance_state"` // One of Decorative, Inoperative, Asserted, Demonstrated, Holding, or Untested — the single control-health verdict for this requirement.
	UnexercisedBindingCount *float64 `json:"unexercised_binding_count"` // How many of this control's step bindings have never been evaluated.
	WitnessIsPartiallyScoped *bool `json:"witness_is_partially_scoped"` // TRUE when a control has a computed witness but at least one of its step bindings has never been exercised by it.
	AccountableRole *string `json:"accountable_role"` // The role answerable for this control operating as designed.
	AccountableAgent *string `json:"accountable_agent"` // The person currently holding the accountable role for this control.
	HasNamedOwner *bool `json:"has_named_owner"` // TRUE when a role has been named as accountable for this control.
	IsOrphanedBlockingControl *bool `json:"is_orphaned_blocking_control"` // TRUE for a blocking control with nobody named as accountable for it.
	IsUnwatchedAndUnowned *bool `json:"is_unwatched_and_unowned"` // TRUE for a blocking control that nothing computes and nobody owns.
	AttestationExposureNote *string `json:"attestation_exposure_note"` // States, per control, what kind of exposure attesting to it creates.
	UnwatchedUnownedFlag *string `json:"unwatched_unowned_flag"` // Constant marker echoed when this control is both unwatched and unowned.
	ControlledTerm *string `json:"controlled_term"` // Controlled vocabulary term this requirement's concept maps to, if any.
	UsesControlledVocabulary *bool `json:"uses_controlled_vocabulary"` // TRUE when this requirement points at a controlled term instead of only free-texting the concept.
	SemanticTypeIri *string `json:"semantic_type_iri"` // Exact PKO class IRI.
	ErbErrors map[string]string `json:"_erb_errors,omitempty"`
	erbAggregates map[string]Value
}

// CalcName computes the Name calculated field
// Human-readable calculated display alias for the Requirements row.
// Formula: ={{Label}}
func (tc *Requirement) CalcName() *string {
	return toStringPtr(vStr(tc.Label))
}

// CalcIsBoundToAnyStep computes the IsBoundToAnyStep calculated field
// TRUE when at least one step carries this requirement.
// Formula: ={{StepBindingCount}} > 0
func (tc *Requirement) CalcIsBoundToAnyStep() *bool {
	return toBoolPtr(erbCmp(vNum(tc.StepBindingCount), ">", vI(0)))
}

// CalcHasEverBeenEvaluated computes the HasEverBeenEvaluated calculated field
// TRUE when this requirement has at least one satisfaction record in the model.
// Formula: ={{SatisfactionRecordCount}} > 0
func (tc *Requirement) CalcHasEverBeenEvaluated() *bool {
	return toBoolPtr(erbCmp(vNum(tc.SatisfactionRecordCount), ">", vI(0)))
}

// CalcIsInoperativeControl computes the IsInoperativeControl calculated field
// TRUE for a blocking requirement that is attached to a step in the specification but has never once been evaluated on any execution.
// Formula: =AND({{IsBlocking}}, {{IsBoundToAnyStep}}, NOT({{HasEverBeenEvaluated}}))
func (tc *Requirement) CalcIsInoperativeControl() *bool {
	return toBoolPtr(erbAnd(erbIsTrue(vBool(tc.IsBlocking)), erbBool3(vBool(tc.IsBoundToAnyStep)), erbBool3(erbNot(erbBool3(vBool(tc.HasEverBeenEvaluated))))))
}

// CalcIsDecorativeControl computes the IsDecorativeControl calculated field
// TRUE for a blocking requirement that is not attached to any step at all.
// Formula: =AND({{IsBlocking}}, NOT({{IsBoundToAnyStep}}))
func (tc *Requirement) CalcIsDecorativeControl() *bool {
	return toBoolPtr(erbAnd(erbIsTrue(vBool(tc.IsBlocking)), erbBool3(erbNot(erbBool3(vBool(tc.IsBoundToAnyStep))))))
}

// CalcHasEverProducedNegative computes the HasEverProducedNegative calculated field
// TRUE when this requirement has at least once been scored as anything other than Satisfied.
// Formula: ={{NegativeOutcomeCount}} > 0
func (tc *Requirement) CalcHasEverProducedNegative() *bool {
	return toBoolPtr(erbCmp(vNum(tc.NegativeOutcomeCount), ">", vI(0)))
}

// CalcIsUnfalsifiedControl computes the IsUnfalsifiedControl calculated field
// TRUE for a blocking control that HAS been evaluated at least once and has never returned a negative result.
// Formula: =AND({{IsBlocking}}, {{HasEverBeenEvaluated}}, NOT({{HasEverProducedNegative}}))
func (tc *Requirement) CalcIsUnfalsifiedControl() *bool {
	return toBoolPtr(erbAnd(erbIsTrue(vBool(tc.IsBlocking)), erbBool3(vBool(tc.HasEverBeenEvaluated)), erbBool3(erbNot(erbBool3(vBool(tc.HasEverProducedNegative))))))
}

// CalcClaimsAWitnessField computes the ClaimsAWitnessField calculated field
// TRUE when this requirement names a field it claims computes it.
// Formula: ={{WitnessFieldName}} <> ""
func (tc *Requirement) CalcClaimsAWitnessField() *bool {
	return toBoolPtr(erbIsNotBlank(vStr(tc.WitnessFieldName)))
}

// CalcDerivedHasComputedWitness computes the DerivedHasComputedWitness calculated field
// Whether this requirement genuinely has a computed witness, derived from the field catalog rather than asserted.
// Formula: =AND({{ClaimsAWitnessField}}, {{NamedWitnessFieldExists}})
func (tc *Requirement) CalcDerivedHasComputedWitness() *bool {
	return toBoolPtr(erbAnd(erbBool3(vBool(tc.ClaimsAWitnessField)), erbBool3(vBool(tc.NamedWitnessFieldExists))))
}

// CalcWitnessClaimIsUnverified computes the WitnessClaimIsUnverified calculated field
// TRUE when the hand-typed HasComputedWitness flag disagrees with what the field catalog says.
// Formula: =NOT({{HasComputedWitness}} = {{DerivedHasComputedWitness}})
func (tc *Requirement) CalcWitnessClaimIsUnverified() *bool {
	return toBoolPtr(erbNot(erbBool3(erbEq(erbNullif(vBool(tc.HasComputedWitness)), vBool(tc.DerivedHasComputedWitness)))))
}

// CalcIsUnwitnessedBlockingControl computes the IsUnwitnessedBlockingControl calculated field
// TRUE for a blocking control with no verified computed witness behind it.
// Formula: =AND({{IsBlocking}}, NOT({{DerivedHasComputedWitness}}))
func (tc *Requirement) CalcIsUnwitnessedBlockingControl() *bool {
	return toBoolPtr(erbAnd(erbIsTrue(vBool(tc.IsBlocking)), erbBool3(erbNot(erbBool3(vBool(tc.DerivedHasComputedWitness))))))
}

// CalcWitnessFireCount computes the WitnessFireCount calculated field
// How many times this requirement's evaluation has returned a non-Satisfied result.
// Formula: ={{NegativeOutcomeCount}}
func (tc *Requirement) CalcWitnessFireCount() *float64 {
	return toFloatPtr(vNum(tc.NegativeOutcomeCount))
}

// CalcWitnessHasNeverFired computes the WitnessHasNeverFired calculated field
// TRUE for a requirement that has a computed witness which has never once returned a negative result.
// Formula: =AND({{HasComputedWitness}}, {{WitnessFireCount}} = 0)
func (tc *Requirement) CalcWitnessHasNeverFired() *bool {
	return toBoolPtr(erbAnd(erbIsTrue(vBool(tc.HasComputedWitness)), erbBool3(erbEq(vNum(tc.WitnessFireCount), vI(0)))))
}

// CalcEvaluationSampleSize computes the EvaluationSampleSize calculated field
// How many times this requirement has been evaluated at all.
// Formula: ={{SatisfactionRecordCount}}
func (tc *Requirement) CalcEvaluationSampleSize() *float64 {
	return toFloatPtr(vNum(tc.SatisfactionRecordCount))
}

// CalcHasMeaningfulSample computes the HasMeaningfulSample calculated field
// TRUE when this requirement has been evaluated often enough that a clean record is informative.
// Formula: ={{EvaluationSampleSize}} >= {{MinimumSampleForAssurance}}
func (tc *Requirement) CalcHasMeaningfulSample() *bool {
	return toBoolPtr(erbCmp(vNum(tc.EvaluationSampleSize), ">=", erbNullif(vInt(tc.MinimumSampleForAssurance))))
}

// CalcIsUntestedWitness computes the IsUntestedWitness calculated field
// TRUE for a witness that has never fired and has not been exercised enough for that silence to mean anything.
// Formula: =AND({{WitnessHasNeverFired}}, NOT({{HasMeaningfulSample}}))
func (tc *Requirement) CalcIsUntestedWitness() *bool {
	return toBoolPtr(erbAnd(erbBool3(vBool(tc.WitnessHasNeverFired)), erbBool3(erbNot(erbBool3(vBool(tc.HasMeaningfulSample))))))
}

// CalcIsEvidencedHoldingControl computes the IsEvidencedHoldingControl calculated field
// TRUE for a witness that has never fired across a sample large enough for that to constitute evidence.
// Formula: =AND({{WitnessHasNeverFired}}, {{HasMeaningfulSample}})
func (tc *Requirement) CalcIsEvidencedHoldingControl() *bool {
	return toBoolPtr(erbAnd(erbBool3(vBool(tc.WitnessHasNeverFired)), erbBool3(vBool(tc.HasMeaningfulSample))))
}

// CalcControlAssuranceState computes the ControlAssuranceState calculated field
// One of Decorative, Inoperative, Asserted, Demonstrated, Holding, or Untested — the single control-health verdict for this requirement.
// Formula: =IF(NOT({{IsBoundToAnyStep}}), "Decorative", IF(NOT({{HasEverBeenEvaluated}}), "Inoperative", IF(NOT({{HasComputedWitness}}), "Asserted", IF({{WitnessFireCount}} > 0, "Demonstrated", IF({{HasMeaningfulSample}}, "Holding", "Untested")))))
func (tc *Requirement) CalcControlAssuranceState() *string {
	return toStringPtr(erbIf(erbBool3(erbNot(erbBool3(vBool(tc.IsBoundToAnyStep)))), func() Value { return vS("Decorative") }, func() Value { return erbIf(erbBool3(erbNot(erbBool3(vBool(tc.HasEverBeenEvaluated)))), func() Value { return vS("Inoperative") }, func() Value { return erbIf(erbBool3(erbNot(erbIsTrue(vBool(tc.HasComputedWitness)))), func() Value { return vS("Asserted") }, func() Value { return erbIf(erbBool3(erbCmp(vNum(tc.WitnessFireCount), ">", vI(0))), func() Value { return vS("Demonstrated") }, func() Value { return erbIf(erbBool3(vBool(tc.HasMeaningfulSample)), func() Value { return vS("Holding") }, func() Value { return vS("Untested") }) }) }) }) }))
}

// CalcWitnessIsPartiallyScoped computes the WitnessIsPartiallyScoped calculated field
// TRUE when a control has a computed witness but at least one of its step bindings has never been exercised by it.
// Formula: =AND({{HasComputedWitness}}, {{UnexercisedBindingCount}} > 0)
func (tc *Requirement) CalcWitnessIsPartiallyScoped() *bool {
	return toBoolPtr(erbAnd(erbIsTrue(vBool(tc.HasComputedWitness)), erbBool3(erbCmp(vNum(tc.UnexercisedBindingCount), ">", vI(0)))))
}

// CalcHasNamedOwner computes the HasNamedOwner calculated field
// TRUE when a role has been named as accountable for this control.
// Formula: ={{AccountableRole}} <> ""
func (tc *Requirement) CalcHasNamedOwner() *bool {
	return toBoolPtr(erbIsNotBlank(vStr(tc.AccountableRole)))
}

// CalcIsOrphanedBlockingControl computes the IsOrphanedBlockingControl calculated field
// TRUE for a blocking control with nobody named as accountable for it.
// Formula: =AND({{IsBlocking}}, NOT({{HasNamedOwner}}))
func (tc *Requirement) CalcIsOrphanedBlockingControl() *bool {
	return toBoolPtr(erbAnd(erbIsTrue(vBool(tc.IsBlocking)), erbBool3(erbNot(erbBool3(vBool(tc.HasNamedOwner))))))
}

// CalcIsUnwatchedAndUnowned computes the IsUnwatchedAndUnowned calculated field
// TRUE for a blocking control that nothing computes and nobody owns.
// Formula: =AND({{IsBlocking}}, NOT({{HasComputedWitness}}), NOT({{HasNamedOwner}}))
func (tc *Requirement) CalcIsUnwatchedAndUnowned() *bool {
	return toBoolPtr(erbAnd(erbIsTrue(vBool(tc.IsBlocking)), erbBool3(erbNot(erbIsTrue(vBool(tc.HasComputedWitness)))), erbBool3(erbNot(erbBool3(vBool(tc.HasNamedOwner))))))
}

// CalcAttestationExposureNote computes the AttestationExposureNote calculated field
// States, per control, what kind of exposure attesting to it creates.
// Formula: =IF(NOT({{IsBlocking}}), "", IF({{IsUnwatchedAndUnowned}}, "Unwatched and unowned: exposure defaults to the signatory.", IF({{IsOrphanedBlockingControl}}, "Witnessed but unowned: no named accountability.", IF(NOT({{HasComputedWitness}}), "Owned but unwitnessed: rests on human judgement.", ""))))
func (tc *Requirement) CalcAttestationExposureNote() *string {
	return toStringPtr(erbIf(erbBool3(erbNot(erbIsTrue(vBool(tc.IsBlocking)))), func() Value { return vS("") }, func() Value { return erbIf(erbBool3(vBool(tc.IsUnwatchedAndUnowned)), func() Value { return vS("Unwatched and unowned: exposure defaults to the signatory.") }, func() Value { return erbIf(erbBool3(vBool(tc.IsOrphanedBlockingControl)), func() Value { return vS("Witnessed but unowned: no named accountability.") }, func() Value { return erbIf(erbBool3(erbNot(erbIsTrue(vBool(tc.HasComputedWitness)))), func() Value { return vS("Owned but unwitnessed: rests on human judgement.") }, func() Value { return vS("") }) }) }) }))
}

// CalcUnwatchedUnownedFlag computes the UnwatchedUnownedFlag calculated field
// Constant marker echoed when this control is both unwatched and unowned.
// Formula: =IF({{IsUnwatchedAndUnowned}}, "unwatched-unowned", "")
func (tc *Requirement) CalcUnwatchedUnownedFlag() *string {
	return toStringPtr(erbIf(erbBool3(vBool(tc.IsUnwatchedAndUnowned)), func() Value { return vS("unwatched-unowned") }, func() Value { return vS("") }))
}

// CalcUsesControlledVocabulary computes the UsesControlledVocabulary calculated field
// TRUE when this requirement points at a controlled term instead of only free-texting the concept.
// Formula: ={{ControlledTerm}} <> ""
func (tc *Requirement) CalcUsesControlledVocabulary() *bool {
	return toBoolPtr(erbIsNotBlank(vStr(tc.ControlledTerm)))
}

// erbComputeCalculations computes every calculated field of the row in dependency order.
func (tc *Requirement) erbComputeCalculations() {
	// Level 1
	calcGuard(tc, "name", func() { tc.Name = tc.CalcName() })
	calcGuard(tc, "is_bound_to_any_step", func() { tc.IsBoundToAnyStep = tc.CalcIsBoundToAnyStep() })
	calcGuard(tc, "has_ever_been_evaluated", func() { tc.HasEverBeenEvaluated = tc.CalcHasEverBeenEvaluated() })
	calcGuard(tc, "has_ever_produced_negative", func() { tc.HasEverProducedNegative = tc.CalcHasEverProducedNegative() })
	calcGuard(tc, "claims_a_witness_field", func() { tc.ClaimsAWitnessField = tc.CalcClaimsAWitnessField() })
	calcGuard(tc, "witness_fire_count", func() { tc.WitnessFireCount = tc.CalcWitnessFireCount() })
	calcGuard(tc, "evaluation_sample_size", func() { tc.EvaluationSampleSize = tc.CalcEvaluationSampleSize() })
	calcGuard(tc, "witness_is_partially_scoped", func() { tc.WitnessIsPartiallyScoped = tc.CalcWitnessIsPartiallyScoped() })
	calcGuard(tc, "has_named_owner", func() { tc.HasNamedOwner = tc.CalcHasNamedOwner() })
	calcGuard(tc, "uses_controlled_vocabulary", func() { tc.UsesControlledVocabulary = tc.CalcUsesControlledVocabulary() })
	// Level 2
	calcGuard(tc, "is_inoperative_control", func() { tc.IsInoperativeControl = tc.CalcIsInoperativeControl() })
	calcGuard(tc, "is_decorative_control", func() { tc.IsDecorativeControl = tc.CalcIsDecorativeControl() })
	calcGuard(tc, "is_unfalsified_control", func() { tc.IsUnfalsifiedControl = tc.CalcIsUnfalsifiedControl() })
	calcGuard(tc, "derived_has_computed_witness", func() { tc.DerivedHasComputedWitness = tc.CalcDerivedHasComputedWitness() })
	calcGuard(tc, "witness_has_never_fired", func() { tc.WitnessHasNeverFired = tc.CalcWitnessHasNeverFired() })
	calcGuard(tc, "has_meaningful_sample", func() { tc.HasMeaningfulSample = tc.CalcHasMeaningfulSample() })
	calcGuard(tc, "is_orphaned_blocking_control", func() { tc.IsOrphanedBlockingControl = tc.CalcIsOrphanedBlockingControl() })
	calcGuard(tc, "is_unwatched_and_unowned", func() { tc.IsUnwatchedAndUnowned = tc.CalcIsUnwatchedAndUnowned() })
	// Level 3
	calcGuard(tc, "witness_claim_is_unverified", func() { tc.WitnessClaimIsUnverified = tc.CalcWitnessClaimIsUnverified() })
	calcGuard(tc, "is_unwitnessed_blocking_control", func() { tc.IsUnwitnessedBlockingControl = tc.CalcIsUnwitnessedBlockingControl() })
	calcGuard(tc, "is_untested_witness", func() { tc.IsUntestedWitness = tc.CalcIsUntestedWitness() })
	calcGuard(tc, "is_evidenced_holding_control", func() { tc.IsEvidencedHoldingControl = tc.CalcIsEvidencedHoldingControl() })
	calcGuard(tc, "control_assurance_state", func() { tc.ControlAssuranceState = tc.CalcControlAssuranceState() })
	calcGuard(tc, "attestation_exposure_note", func() { tc.AttestationExposureNote = tc.CalcAttestationExposureNote() })
	calcGuard(tc, "unwatched_unowned_flag", func() { tc.UnwatchedUnownedFlag = tc.CalcUnwatchedUnownedFlag() })
}

// ComputeAll computes every calculated field from the row's current inputs.
func (tc *Requirement) ComputeAll() *Requirement {
	tc.erbComputeCalculations()
	return tc
}

