func (tc *Requirement) erbLoad(row map[string]any) {
	for key, value := range row {
		switch key {
		case "requirement_id", "name", "label", "requirement_type", "statement", "rationale", "is_blocking", "satisfaction_record_count", "step_binding_count", "is_bound_to_any_step", "has_ever_been_evaluated", "negative_outcome_count", "is_inoperative_control", "is_decorative_control", "has_computed_witness", "witness_field_name", "has_ever_produced_negative", "is_unfalsified_control", "claims_a_witness_field", "named_witness_field_exists", "derived_has_computed_witness", "witness_claim_is_unverified", "is_unwitnessed_blocking_control", "witness_fire_count", "witness_has_never_fired", "evaluation_sample_size", "has_meaningful_sample", "minimum_sample_for_assurance", "is_untested_witness", "is_evidenced_holding_control", "control_assurance_state", "unexercised_binding_count", "witness_is_partially_scoped", "accountable_role", "accountable_agent", "has_named_owner", "is_orphaned_blocking_control", "is_unwatched_and_unowned", "attestation_exposure_note", "unwatched_unowned_flag", "controlled_term", "uses_controlled_vocabulary", "semantic_type_iri":
			tc.erbSet(key, fromJSON(value))
		}
	}
}

func (tc *Requirement) erbErrors() map[string]string {
	if tc.ErbErrors == nil {
		tc.ErbErrors = map[string]string{}
	}
	return tc.ErbErrors
}

func (tc *Requirement) erbResetErrors() { tc.ErbErrors = nil }

func (tc *Requirement) erbAggregate(name string) Value { return tc.erbAggregates[name] }

func (tc *Requirement) erbSetAggregate(name string, v Value) {
	if tc.erbAggregates == nil {
		tc.erbAggregates = map[string]Value{}
	}
	tc.erbAggregates[name] = v
}

// LoadRequirementRecords reads Requirements rows from a JSON array file.
func LoadRequirementRecords(path string) ([]Requirement, error) {
	records, err := loadRecords(path, func() Record { return &Requirement{} })
	if err != nil {
		return nil, err
	}
	rows := make([]Requirement, len(records))
	for i, r := range records {
		rows[i] = *r.(*Requirement)
	}
	return rows, nil
}

// =============================================================================
// STEPREQUIREMENTS TABLE
// Many-to-many Step/Requirement semantics normalized into an ERB junction table.
// =============================================================================

// StepRequirement represents a row in the StepRequirements table
type StepRequirement struct {
	StepRequirementId string `json:"step_requirement_id"` // Stored logical identifier for one StepRequirements row.
	Name *string `json:"name"` // Human-readable calculated display alias for the StepRequirements row.
	Step *string `json:"step"` // Step side of the relationship.
	Requirement *string `json:"requirement"` // Requirement side of the relationship.
	RequirementIsBlocking *bool `json:"requirement_is_blocking"` // Whether this spec-side step/requirement binding names a blocking control.
	BlockingStepKey *string `json:"blocking_step_key"` // Echoes the Step id only when the bound requirement is blocking; empty otherwise.
	StepWhenBlocking *string `json:"step_when_blocking"` // Echoes the step id when the bound requirement is blocking, blank otherwise.
	RequirementLacksWitness *bool `json:"requirement_lacks_witness"` // Whether the requirement bound at this step is a blocking control with no computed witness.
	UnwitnessedStepKey *string `json:"unwitnessed_step_key"` // Echoes the step id when the requirement bound here has no computed witness.
	SatisfactionCountForBinding *float64 `json:"satisfaction_count_for_binding"` // How many times this specific (step, requirement) binding has been evaluated in any execution.
	BindingWasEverExercised *bool `json:"binding_was_ever_exercised"` // TRUE when this specific (step, requirement) pair has been evaluated at least once.
	IsUnexercisedBlockingBinding *bool `json:"is_unexercised_blocking_binding"` // TRUE for a blocking control bound to a step where it has never actually been evaluated.
	UnexercisedBindingRequirementKey *string `json:"unexercised_binding_requirement_key"` // Echoes the requirement id when this binding has never been exercised.
	ErbErrors map[string]string `json:"_erb_errors,omitempty"`
	erbAggregates map[string]Value
}

// CalcName computes the Name calculated field
// Human-readable calculated display alias for the StepRequirements row.
// Formula: ={{Step}} & " / " & {{Requirement}}
func (tc *StepRequirement) CalcName() *string {
	return toStringPtr(erbConcat(erbText(vStr(tc.Step)), vS(" / "), erbText(vStr(tc.Requirement))))
}

// CalcBlockingStepKey computes the BlockingStepKey calculated field
// Echoes the Step id only when the bound requirement is blocking; empty otherwise.
