// CalcIsUnexercisedBlockingBinding computes the IsUnexercisedBlockingBinding calculated field
// TRUE for a blocking control bound to a step where it has never actually been evaluated.
// Formula: =AND({{RequirementIsBlocking}}, NOT({{BindingWasEverExercised}}))
func (tc *StepRequirement) CalcIsUnexercisedBlockingBinding() *bool {
	return toBoolPtr(erbAnd(erbBool3(vBool(tc.RequirementIsBlocking)), erbBool3(erbNot(erbBool3(vBool(tc.BindingWasEverExercised))))))
}

// CalcUnexercisedBindingRequirementKey computes the UnexercisedBindingRequirementKey calculated field
// Echoes the requirement id when this binding has never been exercised.
// Formula: =IF({{IsUnexercisedBlockingBinding}}, {{Requirement}}, "")
func (tc *StepRequirement) CalcUnexercisedBindingRequirementKey() *string {
	return toStringPtr(erbIf(erbBool3(vBool(tc.IsUnexercisedBlockingBinding)), func() Value { return vStr(tc.Requirement) }, func() Value { return vS("") }))
}

