type ProcedureResource struct {
	ProcedureResourceId string `json:"procedure_resource_id"` // Stored logical identifier for one ProcedureResources row.
	Name *string `json:"name"` // Human-readable calculated display alias for the ProcedureResources row.
	ProcedureVersion *string `json:"procedure_version"` // Procedure version.
	Resource *string `json:"resource"` // Referenced or source resource.
	Relation *string `json:"relation"` // wasExtractedFrom, references, generated, used, or another declared relation.
	RelationIri *string `json:"relation_iri"` // Exact semantic property IRI for the relation.
	ErbErrors map[string]string `json:"_erb_errors,omitempty"`
	erbAggregates map[string]Value
}

// CalcName computes the Name calculated field
// Human-readable calculated display alias for the ProcedureResources row.
// Formula: ={{ProcedureVersion}} & " / " & {{Resource}}
func (tc *ProcedureResource) CalcName() *string {
	return toStringPtr(erbConcat(erbText(vStr(tc.ProcedureVersion)), vS(" / "), erbText(vStr(tc.Resource))))
}

// CalcRelationIri computes the RelationIri calculated field
// Exact semantic property IRI for the relation.
// Formula: =IF({{Relation}} = "wasExtractedFrom", "https://w3id.org/pko#wasExtractedFrom", "http://purl.org/dc/terms/references")
func (tc *ProcedureResource) CalcRelationIri() *string {
	return toStringPtr(erbIf(erbBool3(erbEq(erbNullif(vStr(tc.Relation)), vS("wasExtractedFrom"))), func() Value { return vS("https://w3id.org/pko#wasExtractedFrom") }, func() Value { return vS("http://purl.org/dc/terms/references") }))
}

// erbComputeCalculations computes every calculated field of the row in dependency order.
func (tc *ProcedureResource) erbComputeCalculations() {
	// Level 1
	calcGuard(tc, "name", func() { tc.Name = tc.CalcName() })
	calcGuard(tc, "relation_iri", func() { tc.RelationIri = tc.CalcRelationIri() })
}

// ComputeAll computes every calculated field from the row's current inputs.
func (tc *ProcedureResource) ComputeAll() *ProcedureResource {
	tc.erbComputeCalculations()
	return tc
}

