// =============================================================================
// KNOWLEDGEGAPS TABLE
// Known unknowns and missing procedural coverage. Explicit ERB-PKO extension used to govern scope and prevent silent incompleteness.
// =============================================================================

// KnowledgeGap represents a row in the KnowledgeGaps table
type KnowledgeGap struct {
	KnowledgeGapId string `json:"knowledge_gap_id"` // Stored logical identifier for one KnowledgeGaps row.
	Name *string `json:"name"` // Human-readable calculated display alias for the KnowledgeGaps row.
	ProcedureVersion *string `json:"procedure_version"` // Affected procedure version.
	Step *string `json:"step"` // Affected step.
	Statement *string `json:"statement"` // What is not yet known or represented.
	Severity *string `json:"severity"` // Low, Medium, High, or Critical.
	BlockingKind *string `json:"blocking_kind"` // Blocking or NonBlocking.
	Status *string `json:"status"` // Open, Investigating, Resolved, AcceptedRisk, or Closed.
	OwnerRole *string `json:"owner_role"` // Role responsible for resolving the gap.
	IdentifiedAt *string `json:"identified_at"` // Time the gap was identified.
	ResolutionPlan *string `json:"resolution_plan"` // Resolution plan or final resolution.
	IsOpen *bool `json:"is_open"` // TRUE when the gap remains open.
	OpenGapVersionKey *string `json:"open_gap_version_key"` // Echoes the ProcedureVersion id for open high-severity knowledge gaps.
	IsBlocking *bool `json:"is_blocking"` // TRUE when this gap is declared blocking rather than informational.
	IsOpenAndBlocking *bool `json:"is_open_and_blocking"` // TRUE when this gap is both unresolved and declared blocking.
	EvaluationContext *string `json:"evaluation_context"` // The evaluation context this row's time-dependent witnesses are judged under.
	AsOfInstant *string `json:"as_of_instant"` // The evaluation instant this row's time-dependent witnesses are judged against.
	DaysOpen *int `json:"days_open"` // Days this gap has been unresolved, or zero once closed.
	ToleranceDays *int `json:"tolerance_days"` // How long a gap of this severity may remain open before it becomes a governance failure in its own right.
	IsOverdueGap *bool `json:"is_overdue_gap"` // TRUE when this acknowledged unknown has outlived the tolerance for its severity.
	OwnerAgent *string `json:"owner_agent"` // The agent currently holding the role that owns resolving this gap.
	OwnerIsStillEngaged *bool `json:"owner_is_still_engaged"` // Whether the agent responsible for closing this gap still holds a role here.
	HasResolutionPlan *bool `json:"has_resolution_plan"` // TRUE when someone has written down how this gap would be closed.
	IsAbandonedUnknown *bool `json:"is_abandoned_unknown"` // TRUE when an overdue gap has either no plan or no living owner — an admission of ignorance that nobody is acting on.
	OpenBlockingGapVersionKey *string `json:"open_blocking_gap_version_key"` // Composite-key echo: this gap's procedure version when the gap is both open and blocking, blank otherwise.
	OwnerRoleIsVacated *bool `json:"owner_role_is_vacated"` // Whether the role that owns this gap is currently vacated.
	IsOwnerlessOpenGap *bool `json:"is_ownerless_open_gap"` // An open gap whose owning role nobody currently holds — an acknowledged unknown with nobody accountable for closing it.
	SemanticTypeIri *string `json:"semantic_type_iri"` // Extension class IRI.
	ErbErrors map[string]string `json:"_erb_errors,omitempty"`
	erbAggregates map[string]Value
}

// CalcName computes the Name calculated field
// Human-readable calculated display alias for the KnowledgeGaps row.
// Formula: ={{Severity}} & ": " & LEFT({{Statement}}, 60)
func (tc *KnowledgeGap) CalcName() *string {
	return toStringPtr(erbConcat(erbText(vStr(tc.Severity)), vS(": "), erbText(erbLeft(vStr(tc.Statement), vI(60)))))
}

// CalcIsOpen computes the IsOpen calculated field
// TRUE when the gap remains open.
// Formula: =OR({{Status}} = "Open", {{Status}} = "Investigating")
func (tc *KnowledgeGap) CalcIsOpen() *bool {
	return toBoolPtr(erbOr(erbBool3(erbEq(erbNullif(vStr(tc.Status)), vS("Open"))), erbBool3(erbEq(erbNullif(vStr(tc.Status)), vS("Investigating")))))
}

// CalcOpenGapVersionKey computes the OpenGapVersionKey calculated field
// Echoes the ProcedureVersion id for open high-severity knowledge gaps.
// Formula: =IF(AND({{IsOpen}}, {{Severity}} = "High"), {{ProcedureVersion}}, "")
func (tc *KnowledgeGap) CalcOpenGapVersionKey() *string {
	return toStringPtr(erbIf(erbBool3(erbAnd(erbBool3(vBool(tc.IsOpen)), erbBool3(erbEq(erbNullif(vStr(tc.Severity)), vS("High"))))), func() Value { return vStr(tc.ProcedureVersion) }, func() Value { return vS("") }))
}

// CalcIsBlocking computes the IsBlocking calculated field
// TRUE when this gap is declared blocking rather than informational.
// Formula: ={{BlockingKind}} = "Blocking"
func (tc *KnowledgeGap) CalcIsBlocking() *bool {
	return toBoolPtr(erbEq(erbNullif(vStr(tc.BlockingKind)), vS("Blocking")))
}

// CalcIsOpenAndBlocking computes the IsOpenAndBlocking calculated field
// TRUE when this gap is both unresolved and declared blocking.
// Formula: =AND({{IsOpen}}, {{IsBlocking}})
func (tc *KnowledgeGap) CalcIsOpenAndBlocking() *bool {
	return toBoolPtr(erbAnd(erbBool3(vBool(tc.IsOpen)), erbBool3(vBool(tc.IsBlocking))))
}

// CalcDaysOpen computes the DaysOpen calculated field
// Days this gap has been unresolved, or zero once closed.
// Formula: =IF({{IsOpen}}, DATETIME_DIFF({{AsOfInstant}}, {{IdentifiedAt}}, "days"), 0)
func (tc *KnowledgeGap) CalcDaysOpen() *int {
	return toIntPtr(erbInteger(erbIf(erbBool3(vBool(tc.IsOpen)), func() Value { return erbDatetimeDiff(vStr(tc.AsOfInstant), vStr(tc.IdentifiedAt), vS("days")) }, func() Value { return vI(0) })))
}

// CalcToleranceDays computes the ToleranceDays calculated field
// How long a gap of this severity may remain open before it becomes a governance failure in its own right.
// Formula: =IF({{Severity}} = "High", 30, IF({{Severity}} = "Medium", 90, 180))
func (tc *KnowledgeGap) CalcToleranceDays() *int {
	return toIntPtr(erbInteger(erbIf(erbBool3(erbEq(erbNullif(vStr(tc.Severity)), vS("High"))), func() Value { return vI(30) }, func() Value { return erbIf(erbBool3(erbEq(erbNullif(vStr(tc.Severity)), vS("Medium"))), func() Value { return vI(90) }, func() Value { return vI(180) }) })))
}

// CalcIsOverdueGap computes the IsOverdueGap calculated field
// TRUE when this acknowledged unknown has outlived the tolerance for its severity.
// Formula: ={{DaysOpen}} > {{ToleranceDays}}
func (tc *KnowledgeGap) CalcIsOverdueGap() *bool {
	return toBoolPtr(erbCmp(vInt(tc.DaysOpen), ">", vInt(tc.ToleranceDays)))
}

// CalcHasResolutionPlan computes the HasResolutionPlan calculated field
// TRUE when someone has written down how this gap would be closed.
// Formula: ={{ResolutionPlan}} <> ""
func (tc *KnowledgeGap) CalcHasResolutionPlan() *bool {
	return toBoolPtr(erbIsNotBlank(vStr(tc.ResolutionPlan)))
}

// CalcIsAbandonedUnknown computes the IsAbandonedUnknown calculated field
// TRUE when an overdue gap has either no plan or no living owner — an admission of ignorance that nobody is acting on.
// Formula: =AND({{IsOverdueGap}}, OR(NOT({{HasResolutionPlan}}), NOT({{OwnerIsStillEngaged}})))
func (tc *KnowledgeGap) CalcIsAbandonedUnknown() *bool {
	return toBoolPtr(erbAnd(erbBool3(vBool(tc.IsOverdueGap)), erbBool3(erbOr(erbBool3(erbNot(erbBool3(vBool(tc.HasResolutionPlan)))), erbBool3(erbNot(erbBool3(vBool(tc.OwnerIsStillEngaged))))))))
}

// CalcOpenBlockingGapVersionKey computes the OpenBlockingGapVersionKey calculated field
// Composite-key echo: this gap's procedure version when the gap is both open and blocking, blank otherwise.
// Formula: =IF({{IsOpenAndBlocking}}, {{ProcedureVersion}}, "")
func (tc *KnowledgeGap) CalcOpenBlockingGapVersionKey() *string {
	return toStringPtr(erbIf(erbBool3(vBool(tc.IsOpenAndBlocking)), func() Value { return vStr(tc.ProcedureVersion) }, func() Value { return vS("") }))
}

// CalcIsOwnerlessOpenGap computes the IsOwnerlessOpenGap calculated field
// An open gap whose owning role nobody currently holds — an acknowledged unknown with nobody accountable for closing it.
// Formula: =AND({{IsOpen}}, {{OwnerRoleIsVacated}})
func (tc *KnowledgeGap) CalcIsOwnerlessOpenGap() *bool {
	return toBoolPtr(erbAnd(erbBool3(vBool(tc.IsOpen)), erbBool3(vBool(tc.OwnerRoleIsVacated))))
}

// erbComputeCalculations computes every calculated field of the row in dependency order.
func (tc *KnowledgeGap) erbComputeCalculations() {
	// Level 1
	calcGuard(tc, "name", func() { tc.Name = tc.CalcName() })
	calcGuard(tc, "is_open", func() { tc.IsOpen = tc.CalcIsOpen() })
	calcGuard(tc, "is_blocking", func() { tc.IsBlocking = tc.CalcIsBlocking() })
	calcGuard(tc, "tolerance_days", func() { tc.ToleranceDays = tc.CalcToleranceDays() })
	calcGuard(tc, "has_resolution_plan", func() { tc.HasResolutionPlan = tc.CalcHasResolutionPlan() })
	// Level 2
	calcGuard(tc, "open_gap_version_key", func() { tc.OpenGapVersionKey = tc.CalcOpenGapVersionKey() })
	calcGuard(tc, "is_open_and_blocking", func() { tc.IsOpenAndBlocking = tc.CalcIsOpenAndBlocking() })
	calcGuard(tc, "days_open", func() { tc.DaysOpen = tc.CalcDaysOpen() })
	calcGuard(tc, "is_ownerless_open_gap", func() { tc.IsOwnerlessOpenGap = tc.CalcIsOwnerlessOpenGap() })
	// Level 3
	calcGuard(tc, "is_overdue_gap", func() { tc.IsOverdueGap = tc.CalcIsOverdueGap() })
	calcGuard(tc, "open_blocking_gap_version_key", func() { tc.OpenBlockingGapVersionKey = tc.CalcOpenBlockingGapVersionKey() })
	// Level 4
	calcGuard(tc, "is_abandoned_unknown", func() { tc.IsAbandonedUnknown = tc.CalcIsAbandonedUnknown() })
}

// ComputeAll computes every calculated field from the row's current inputs.
func (tc *KnowledgeGap) ComputeAll() *KnowledgeGap {
	tc.erbComputeCalculations()
	return tc
}

