func LoadStepExecutionRecords(path string) ([]StepExecution, error) {
	records, err := loadRecords(path, func() Record { return &StepExecution{} })
	if err != nil {
		return nil, err
	}
	rows := make([]StepExecution, len(records))
	for i, r := range records {
		rows[i] = *r.(*StepExecution)
	}
	return rows, nil
}

// =============================================================================
// REQUIREMENTSATISFACTIONS TABLE
// Execution-time evaluations of requirements. Maps to pko:RequirementSatisfaction, refersToRequirement, and hasRequirementSatisfactionLevel.
// =============================================================================

// RequirementSatisfaction represents a row in the RequirementSatisfactions table
type RequirementSatisfaction struct {
	RequirementSatisfactionId string `json:"requirement_satisfaction_id"` // Stored logical identifier for one RequirementSatisfactions row.
	Name *string `json:"name"` // Human-readable calculated display alias for the RequirementSatisfactions row.
	StepExecution *string `json:"step_execution"` // Execution being evaluated.
	Requirement *string `json:"requirement"` // Requirement evaluated.
	SatisfactionLevel *string `json:"satisfaction_level"` // NotEvaluated, NotSatisfied, PartiallySatisfied, or Satisfied.
	Evidence *string `json:"evidence"` // Evidence supporting the evaluation.
	EvaluatedByAgent *string `json:"evaluated_by_agent"` // Agent that evaluated satisfaction.
	EvaluatedAt *string `json:"evaluated_at"` // Evaluation timestamp.
	RequirementIsBlocking *bool `json:"requirement_is_blocking"` // Whether the requirement being evaluated on this satisfaction row is a blocking control.
	IsFullySatisfied *bool `json:"is_fully_satisfied"` // TRUE only when the requirement is recorded as fully Satisfied. PartiallySatisfied, Unsatisfied, Waived, and blank are all FALSE.
	IsBlockingAndUnmet *bool `json:"is_blocking_and_unmet"` // TRUE when a blocking requirement is recorded at anything less than fully Satisfied. This is the control-failure witness at the requirement grain.
	BlockingUnmetStepKey *string `json:"blocking_unmet_step_key"` // Echoes the parent StepExecution id only when this row is a blocking-unmet violation; empty string otherwise.
	BlockingSatisfactionStepKey *string `json:"blocking_satisfaction_step_key"` // Echoes the parent StepExecution id when this satisfaction row concerns a blocking requirement.
	NegativeOutcomeRequirementKey *string `json:"negative_outcome_requirement_key"` // Echoes the Requirement id only when this evaluation came out at less than fully Satisfied.
	EvaluatorAgentKind *string `json:"evaluator_agent_kind"` // What kind of agent evaluated this requirement satisfaction.
	NonHumanEvaluatedHumanControl *bool `json:"non_human_evaluated_human_control"` // TRUE when a blocking requirement was evaluated by a non-human agent.
	RequirementHasComputedWitness *bool `json:"requirement_has_computed_witness"` // Whether the requirement this row evaluates has a computed witness behind it.
	IsAssertedOnly *bool `json:"is_asserted_only"` // TRUE when a blocking requirement is recorded as Satisfied purely on human assertion, with no computed predicate behind it.
	AssertedOnlyExecutionKey *string `json:"asserted_only_execution_key"` // Echoes the grandparent procedure execution id for assertion-only satisfactions.
	ParentProcedureExecution *string `json:"parent_procedure_execution"` // The procedure execution this satisfaction ultimately belongs to.
	StepExecutionWhenScored *string `json:"step_execution_when_scored"` // Echoes the step-execution id when a satisfaction level was actually recorded, blank otherwise.
	IsHumanEvaluated *bool `json:"is_human_evaluated"` // TRUE when a human evaluated this requirement satisfaction.
	RequirementIsApprovalType *string `json:"requirement_is_approval_type"` // The requirement's type, e.g. Approval, Control, Privacy.
	IsInvalidApproval *bool `json:"is_invalid_approval"` // TRUE when an approval-type requirement is not fully satisfied, or was not evaluated by a human.
	ProcedureExecutionOfSatisfaction *string `json:"procedure_execution_of_satisfaction"` // The run this satisfaction belongs to.
	RunWhenInvalidApproval *string `json:"run_when_invalid_approval"` // Echoes the run id when this is an invalid approval, blank otherwise.
	RequirementIsUnfalsified *bool `json:"requirement_is_unfalsified"` // Whether the requirement behind this satisfaction record has never once returned a negative result.
	IsClearanceByUnfalsifiedControl *bool `json:"is_clearance_by_unfalsified_control"` // TRUE when this record cleared a step against a blocking control that has never produced a negative outcome.
	UnfalsifiedClearanceStepKey *string `json:"unfalsified_clearance_step_key"` // Echoes the step execution id when this clearance came from an unfalsified control.
	SpecStepOfExecution *string `json:"spec_step_of_execution"` // The specification step behind the step execution this satisfaction was recorded against.
	BindingKey *string `json:"binding_key"` // The StepRequirements binding this satisfaction record exercised.
	ScoredStepExecutorAgent *string `json:"scored_step_executor_agent"` // The agent who executed the step this satisfaction record scores.
	EvaluatorIsStepExecutor *bool `json:"evaluator_is_step_executor"` // TRUE when the agent who scored this control is the same agent who performed the step being scored.
	RunOwnerAgent *string `json:"run_owner_agent"` // The agent accountable for the whole procedure execution this satisfaction sits inside.
	EvaluatorOwnsTheRun *bool `json:"evaluator_owns_the_run"` // TRUE when the agent scoring this control is the agent accountable for the execution it belongs to.
	IsInterestedPartyAssertion *bool `json:"is_interested_party_assertion"` // TRUE when a blocking control's only evidence is an assertion made by someone with an interest in the outcome.
	HasWrittenEvidence *bool `json:"has_written_evidence"` // TRUE when this satisfaction record carries any evidence text at all.
	IsBareAssertion *bool `json:"is_bare_assertion"` // TRUE when a blocking control was cleared with no computed witness and no written justification.
	InterestedAssertionExecutionKey *string `json:"interested_assertion_execution_key"` // Echoes the parent execution id when this record is an interested-party assertion.
	IsComputedlyWitnessed *bool `json:"is_computedly_witnessed"` // TRUE when this record scores a blocking control that has a computed witness behind it.
	ComputedWitnessExecutionKey *string `json:"computed_witness_execution_key"` // Echoes the parent execution id when this control was computationally witnessed.
	StepExecutorAgent *string `json:"step_executor_agent"` // The agent who executed the step this satisfaction record scores.
	WasScoredAfterAttestation *bool `json:"was_scored_after_attestation"` // TRUE when this control was scored after the run it belongs to had already been attested.
	AttestationInstantForRun *string `json:"attestation_instant_for_run"` // When the parent execution was attested, if it has been.
	PostAttestationScoreExecutionKey *string `json:"post_attestation_score_execution_key"` // Echoes the parent execution id when this control was scored after signature.
	SemanticTypeIri *string `json:"semantic_type_iri"` // Exact PKO class IRI.
	ErbErrors map[string]string `json:"_erb_errors,omitempty"`
	erbAggregates map[string]Value
}

// CalcName computes the Name calculated field
// Human-readable calculated display alias for the RequirementSatisfactions row.
// Formula: ={{Requirement}} & " / " & {{SatisfactionLevel}}
func (tc *RequirementSatisfaction) CalcName() *string {
	return toStringPtr(erbConcat(erbText(vStr(tc.Requirement)), vS(" / "), erbText(vStr(tc.SatisfactionLevel))))
}

// CalcIsFullySatisfied computes the IsFullySatisfied calculated field
// TRUE only when the requirement is recorded as fully Satisfied. PartiallySatisfied, Unsatisfied, Waived, and blank are all FALSE.
// Formula: ={{SatisfactionLevel}} = "Satisfied"
func (tc *RequirementSatisfaction) CalcIsFullySatisfied() *bool {
	return toBoolPtr(erbEq(erbNullif(vStr(tc.SatisfactionLevel)), vS("Satisfied")))
}

// CalcIsBlockingAndUnmet computes the IsBlockingAndUnmet calculated field
// TRUE when a blocking requirement is recorded at anything less than fully Satisfied. This is the control-failure witness at the requirement grain.
// Formula: =AND({{RequirementIsBlocking}}, NOT({{IsFullySatisfied}}))
func (tc *RequirementSatisfaction) CalcIsBlockingAndUnmet() *bool {
	return toBoolPtr(erbAnd(erbBool3(vBool(tc.RequirementIsBlocking)), erbBool3(erbNot(erbBool3(vBool(tc.IsFullySatisfied))))))
}

// CalcBlockingUnmetStepKey computes the BlockingUnmetStepKey calculated field
// Echoes the parent StepExecution id only when this row is a blocking-unmet violation; empty string otherwise.
// Formula: =IF({{IsBlockingAndUnmet}}, {{StepExecution}}, "")
func (tc *RequirementSatisfaction) CalcBlockingUnmetStepKey() *string {
	return toStringPtr(erbIf(erbBool3(vBool(tc.IsBlockingAndUnmet)), func() Value { return vStr(tc.StepExecution) }, func() Value { return vS("") }))
}

// CalcBlockingSatisfactionStepKey computes the BlockingSatisfactionStepKey calculated field
// Echoes the parent StepExecution id when this satisfaction row concerns a blocking requirement.
// Formula: =IF({{RequirementIsBlocking}}, {{StepExecution}}, "")
func (tc *RequirementSatisfaction) CalcBlockingSatisfactionStepKey() *string {
	return toStringPtr(erbIf(erbBool3(vBool(tc.RequirementIsBlocking)), func() Value { return vStr(tc.StepExecution) }, func() Value { return vS("") }))
}

// CalcNegativeOutcomeRequirementKey computes the NegativeOutcomeRequirementKey calculated field
// Echoes the Requirement id only when this evaluation came out at less than fully Satisfied.
// Formula: =IF(NOT({{IsFullySatisfied}}), {{Requirement}}, "")
func (tc *RequirementSatisfaction) CalcNegativeOutcomeRequirementKey() *string {
	return toStringPtr(erbIf(erbBool3(erbNot(erbBool3(vBool(tc.IsFullySatisfied)))), func() Value { return vStr(tc.Requirement) }, func() Value { return vS("") }))
}

// CalcNonHumanEvaluatedHumanControl computes the NonHumanEvaluatedHumanControl calculated field
// TRUE when a blocking requirement was evaluated by a non-human agent.
// Formula: =AND({{RequirementIsBlocking}}, {{EvaluatorAgentKind}} <> "Human")
func (tc *RequirementSatisfaction) CalcNonHumanEvaluatedHumanControl() *bool {
	return toBoolPtr(erbAnd(erbBool3(vBool(tc.RequirementIsBlocking)), erbBool3(erbNe(vStr(tc.EvaluatorAgentKind), vS("Human")))))
}

// CalcIsAssertedOnly computes the IsAssertedOnly calculated field
// TRUE when a blocking requirement is recorded as Satisfied purely on human assertion, with no computed predicate behind it.
// Formula: =AND({{RequirementIsBlocking}}, {{IsFullySatisfied}}, NOT({{RequirementHasComputedWitness}}))
func (tc *RequirementSatisfaction) CalcIsAssertedOnly() *bool {
	return toBoolPtr(erbAnd(erbBool3(vBool(tc.RequirementIsBlocking)), erbBool3(vBool(tc.IsFullySatisfied)), erbBool3(erbNot(erbBool3(vBool(tc.RequirementHasComputedWitness))))))
}

// CalcAssertedOnlyExecutionKey computes the AssertedOnlyExecutionKey calculated field
// Echoes the grandparent procedure execution id for assertion-only satisfactions.
// Formula: =IF({{IsAssertedOnly}}, {{ParentProcedureExecution}}, "")
func (tc *RequirementSatisfaction) CalcAssertedOnlyExecutionKey() *string {
	return toStringPtr(erbIf(erbBool3(vBool(tc.IsAssertedOnly)), func() Value { return vStr(tc.ParentProcedureExecution) }, func() Value { return vS("") }))
}

// CalcStepExecutionWhenScored computes the StepExecutionWhenScored calculated field
// Echoes the step-execution id when a satisfaction level was actually recorded, blank otherwise.
// Formula: =IF({{SatisfactionLevel}} <> "", {{StepExecution}}, "")
func (tc *RequirementSatisfaction) CalcStepExecutionWhenScored() *string {
	return toStringPtr(erbIf(erbBool3(erbIsNotBlank(vStr(tc.SatisfactionLevel))), func() Value { return vStr(tc.StepExecution) }, func() Value { return vS("") }))
}

// CalcIsHumanEvaluated computes the IsHumanEvaluated calculated field
// TRUE when a human evaluated this requirement satisfaction.
// Formula: ={{EvaluatorAgentKind}} = "Human"
func (tc *RequirementSatisfaction) CalcIsHumanEvaluated() *bool {
	return toBoolPtr(erbEq(vStr(tc.EvaluatorAgentKind), vS("Human")))
}

// CalcIsInvalidApproval computes the IsInvalidApproval calculated field
// TRUE when an approval-type requirement is not fully satisfied, or was not evaluated by a human.
// Formula: =AND({{RequirementIsApprovalType}} = "Approval", OR(NOT({{IsFullySatisfied}}), NOT({{IsHumanEvaluated}})))
func (tc *RequirementSatisfaction) CalcIsInvalidApproval() *bool {
	return toBoolPtr(erbAnd(erbBool3(erbEq(vStr(tc.RequirementIsApprovalType), vS("Approval"))), erbBool3(erbOr(erbBool3(erbNot(erbBool3(vBool(tc.IsFullySatisfied)))), erbBool3(erbNot(erbBool3(vBool(tc.IsHumanEvaluated))))))))
}

// CalcRunWhenInvalidApproval computes the RunWhenInvalidApproval calculated field
// Echoes the run id when this is an invalid approval, blank otherwise.
// Formula: =IF({{IsInvalidApproval}}, {{ProcedureExecutionOfSatisfaction}}, "")
func (tc *RequirementSatisfaction) CalcRunWhenInvalidApproval() *string {
	return toStringPtr(erbIf(erbBool3(vBool(tc.IsInvalidApproval)), func() Value { return vStr(tc.ProcedureExecutionOfSatisfaction) }, func() Value { return vS("") }))
}

// CalcIsClearanceByUnfalsifiedControl computes the IsClearanceByUnfalsifiedControl calculated field
// TRUE when this record cleared a step against a blocking control that has never produced a negative outcome.
// Formula: =AND({{IsFullySatisfied}}, {{RequirementIsBlocking}}, {{RequirementIsUnfalsified}})
func (tc *RequirementSatisfaction) CalcIsClearanceByUnfalsifiedControl() *bool {
	return toBoolPtr(erbAnd(erbBool3(vBool(tc.IsFullySatisfied)), erbBool3(vBool(tc.RequirementIsBlocking)), erbBool3(vBool(tc.RequirementIsUnfalsified))))
}

// CalcUnfalsifiedClearanceStepKey computes the UnfalsifiedClearanceStepKey calculated field
// Echoes the step execution id when this clearance came from an unfalsified control.
// Formula: =IF({{IsClearanceByUnfalsifiedControl}}, {{StepExecution}}, "")
func (tc *RequirementSatisfaction) CalcUnfalsifiedClearanceStepKey() *string {
	return toStringPtr(erbIf(erbBool3(vBool(tc.IsClearanceByUnfalsifiedControl)), func() Value { return vStr(tc.StepExecution) }, func() Value { return vS("") }))
}

// CalcEvaluatorIsStepExecutor computes the EvaluatorIsStepExecutor calculated field
// TRUE when the agent who scored this control is the same agent who performed the step being scored.
// Formula: ={{EvaluatedByAgent}} = {{ScoredStepExecutorAgent}}
func (tc *RequirementSatisfaction) CalcEvaluatorIsStepExecutor() *bool {
	return toBoolPtr(erbEq(erbNullif(vStr(tc.EvaluatedByAgent)), vStr(tc.ScoredStepExecutorAgent)))
}

// CalcEvaluatorOwnsTheRun computes the EvaluatorOwnsTheRun calculated field
// TRUE when the agent scoring this control is the agent accountable for the execution it belongs to.
// Formula: ={{EvaluatedByAgent}} = {{RunOwnerAgent}}
func (tc *RequirementSatisfaction) CalcEvaluatorOwnsTheRun() *bool {
	return toBoolPtr(erbEq(erbNullif(vStr(tc.EvaluatedByAgent)), vStr(tc.RunOwnerAgent)))
}

// CalcIsInterestedPartyAssertion computes the IsInterestedPartyAssertion calculated field
// TRUE when a blocking control's only evidence is an assertion made by someone with an interest in the outcome.
// Formula: =AND({{IsAssertedOnly}}, OR({{EvaluatorIsStepExecutor}}, {{EvaluatorOwnsTheRun}}))
func (tc *RequirementSatisfaction) CalcIsInterestedPartyAssertion() *bool {
	return toBoolPtr(erbAnd(erbBool3(vBool(tc.IsAssertedOnly)), erbBool3(erbOr(erbBool3(vBool(tc.EvaluatorIsStepExecutor)), erbBool3(vBool(tc.EvaluatorOwnsTheRun))))))
}

// CalcHasWrittenEvidence computes the HasWrittenEvidence calculated field
// TRUE when this satisfaction record carries any evidence text at all.
// Formula: ={{Evidence}} <> ""
func (tc *RequirementSatisfaction) CalcHasWrittenEvidence() *bool {
	return toBoolPtr(erbIsNotBlank(vStr(tc.Evidence)))
}

// CalcIsBareAssertion computes the IsBareAssertion calculated field
// TRUE when a blocking control was cleared with no computed witness and no written justification.
// Formula: =AND({{IsAssertedOnly}}, NOT({{HasWrittenEvidence}}))
func (tc *RequirementSatisfaction) CalcIsBareAssertion() *bool {
	return toBoolPtr(erbAnd(erbBool3(vBool(tc.IsAssertedOnly)), erbBool3(erbNot(erbBool3(vBool(tc.HasWrittenEvidence))))))
}

// CalcInterestedAssertionExecutionKey computes the InterestedAssertionExecutionKey calculated field
// Echoes the parent execution id when this record is an interested-party assertion.
// Formula: =IF({{IsInterestedPartyAssertion}}, {{ParentProcedureExecution}}, "")
func (tc *RequirementSatisfaction) CalcInterestedAssertionExecutionKey() *string {
	return toStringPtr(erbIf(erbBool3(vBool(tc.IsInterestedPartyAssertion)), func() Value { return vStr(tc.ParentProcedureExecution) }, func() Value { return vS("") }))
}

// CalcIsComputedlyWitnessed computes the IsComputedlyWitnessed calculated field
// TRUE when this record scores a blocking control that has a computed witness behind it.
// Formula: =AND({{RequirementIsBlocking}}, {{RequirementHasComputedWitness}})
func (tc *RequirementSatisfaction) CalcIsComputedlyWitnessed() *bool {
	return toBoolPtr(erbAnd(erbBool3(vBool(tc.RequirementIsBlocking)), erbBool3(vBool(tc.RequirementHasComputedWitness))))
}

// CalcComputedWitnessExecutionKey computes the ComputedWitnessExecutionKey calculated field
// Echoes the parent execution id when this control was computationally witnessed.
// Formula: =IF({{IsComputedlyWitnessed}}, {{ParentProcedureExecution}}, "")
func (tc *RequirementSatisfaction) CalcComputedWitnessExecutionKey() *string {
	return toStringPtr(erbIf(erbBool3(vBool(tc.IsComputedlyWitnessed)), func() Value { return vStr(tc.ParentProcedureExecution) }, func() Value { return vS("") }))
}

// CalcWasScoredAfterAttestation computes the WasScoredAfterAttestation calculated field
// TRUE when this control was scored after the run it belongs to had already been attested.
// Formula: =DATETIME_DIFF({{EvaluatedAt}}, {{AttestationInstantForRun}}, "minutes") > 0
func (tc *RequirementSatisfaction) CalcWasScoredAfterAttestation() *bool {
	return toBoolPtr(erbCmp(erbDatetimeDiff(vStr(tc.EvaluatedAt), vStr(tc.AttestationInstantForRun), vS("minutes")), ">", vI(0)))
}

// CalcPostAttestationScoreExecutionKey computes the PostAttestationScoreExecutionKey calculated field
// Echoes the parent execution id when this control was scored after signature.
// Formula: =IF({{WasScoredAfterAttestation}}, {{ParentProcedureExecution}}, "")
func (tc *RequirementSatisfaction) CalcPostAttestationScoreExecutionKey() *string {
	return toStringPtr(erbIf(erbBool3(vBool(tc.WasScoredAfterAttestation)), func() Value { return vStr(tc.ParentProcedureExecution) }, func() Value { return vS("") }))
}

// erbComputeCalculations computes every calculated field of the row in dependency order.
func (tc *RequirementSatisfaction) erbComputeCalculations() {
	// Level 1
	calcGuard(tc, "name", func() { tc.Name = tc.CalcName() })
	calcGuard(tc, "is_fully_satisfied", func() { tc.IsFullySatisfied = tc.CalcIsFullySatisfied() })
	calcGuard(tc, "blocking_satisfaction_step_key", func() { tc.BlockingSatisfactionStepKey = tc.CalcBlockingSatisfactionStepKey() })
	calcGuard(tc, "non_human_evaluated_human_control", func() { tc.NonHumanEvaluatedHumanControl = tc.CalcNonHumanEvaluatedHumanControl() })
	calcGuard(tc, "step_execution_when_scored", func() { tc.StepExecutionWhenScored = tc.CalcStepExecutionWhenScored() })
	calcGuard(tc, "is_human_evaluated", func() { tc.IsHumanEvaluated = tc.CalcIsHumanEvaluated() })
	calcGuard(tc, "evaluator_is_step_executor", func() { tc.EvaluatorIsStepExecutor = tc.CalcEvaluatorIsStepExecutor() })
	calcGuard(tc, "evaluator_owns_the_run", func() { tc.EvaluatorOwnsTheRun = tc.CalcEvaluatorOwnsTheRun() })
	calcGuard(tc, "has_written_evidence", func() { tc.HasWrittenEvidence = tc.CalcHasWrittenEvidence() })
	calcGuard(tc, "is_computedly_witnessed", func() { tc.IsComputedlyWitnessed = tc.CalcIsComputedlyWitnessed() })
	calcGuard(tc, "was_scored_after_attestation", func() { tc.WasScoredAfterAttestation = tc.CalcWasScoredAfterAttestation() })
	// Level 2
	calcGuard(tc, "is_blocking_and_unmet", func() { tc.IsBlockingAndUnmet = tc.CalcIsBlockingAndUnmet() })
	calcGuard(tc, "negative_outcome_requirement_key", func() { tc.NegativeOutcomeRequirementKey = tc.CalcNegativeOutcomeRequirementKey() })
	calcGuard(tc, "is_asserted_only", func() { tc.IsAssertedOnly = tc.CalcIsAssertedOnly() })
	calcGuard(tc, "is_invalid_approval", func() { tc.IsInvalidApproval = tc.CalcIsInvalidApproval() })
	calcGuard(tc, "is_clearance_by_unfalsified_control", func() { tc.IsClearanceByUnfalsifiedControl = tc.CalcIsClearanceByUnfalsifiedControl() })
	calcGuard(tc, "computed_witness_execution_key", func() { tc.ComputedWitnessExecutionKey = tc.CalcComputedWitnessExecutionKey() })
	calcGuard(tc, "post_attestation_score_execution_key", func() { tc.PostAttestationScoreExecutionKey = tc.CalcPostAttestationScoreExecutionKey() })
	// Level 3
	calcGuard(tc, "blocking_unmet_step_key", func() { tc.BlockingUnmetStepKey = tc.CalcBlockingUnmetStepKey() })
	calcGuard(tc, "asserted_only_execution_key", func() { tc.AssertedOnlyExecutionKey = tc.CalcAssertedOnlyExecutionKey() })
	calcGuard(tc, "run_when_invalid_approval", func() { tc.RunWhenInvalidApproval = tc.CalcRunWhenInvalidApproval() })
	calcGuard(tc, "unfalsified_clearance_step_key", func() { tc.UnfalsifiedClearanceStepKey = tc.CalcUnfalsifiedClearanceStepKey() })
	calcGuard(tc, "is_interested_party_assertion", func() { tc.IsInterestedPartyAssertion = tc.CalcIsInterestedPartyAssertion() })
	calcGuard(tc, "is_bare_assertion", func() { tc.IsBareAssertion = tc.CalcIsBareAssertion() })
	// Level 4
	calcGuard(tc, "interested_assertion_execution_key", func() { tc.InterestedAssertionExecutionKey = tc.CalcInterestedAssertionExecutionKey() })
}

// ComputeAll computes every calculated field from the row's current inputs.
func (tc *RequirementSatisfaction) ComputeAll() *RequirementSatisfaction {
	tc.erbComputeCalculations()
	return tc
}

