// CalcName computes the Name calculated field
// Human-readable calculated display alias for the StewardshipAssignments row.
// Formula: ={{ProcedureVersion}} & " / steward=" & {{StewardRole}}
func (tc *StewardshipAssignment) CalcName() *string {
	return toStringPtr(erbConcat(erbText(vStr(tc.ProcedureVersion)), vS(" / steward="), erbText(vStr(tc.StewardRole))))
}

// CalcHasEverBeenReviewed computes the HasEverBeenReviewed calculated field
// TRUE if at least one review event exists for the stewarded procedure version.
// Formula: ={{CountOfReviewEvents}} > 0
func (tc *StewardshipAssignment) CalcHasEverBeenReviewed() *bool {
	return toBoolPtr(erbCmp(vInt(tc.CountOfReviewEvents), ">", vI(0)))
}

// CalcIsCurrentAssignment computes the IsCurrentAssignment calculated field
// TRUE when this stewardship assignment is in force right now.
// Formula: =AND({{ValidFrom}} <= {{AsOfInstant}}, OR({{ValidTo}} = "", {{ValidTo}} > {{AsOfInstant}}))
func (tc *StewardshipAssignment) CalcIsCurrentAssignment() *bool {
	return toBoolPtr(erbAnd(erbBool3(erbCmp(erbNullif(vStr(tc.ValidFrom)), "<=", vStr(tc.AsOfInstant))), erbBool3(erbOr(erbBool3(erbIsBlank(vStr(tc.ValidTo))), erbBool3(erbCmp(erbNullif(vStr(tc.ValidTo)), ">", vStr(tc.AsOfInstant)))))))
}

// erbComputeCalculations computes every calculated field of the row in dependency order.
func (tc *StewardshipAssignment) erbComputeCalculations() {
	// Level 1
	calcGuard(tc, "name", func() { tc.Name = tc.CalcName() })
	calcGuard(tc, "has_ever_been_reviewed", func() { tc.HasEverBeenReviewed = tc.CalcHasEverBeenReviewed() })
	calcGuard(tc, "is_current_assignment", func() { tc.IsCurrentAssignment = tc.CalcIsCurrentAssignment() })
}

// ComputeAll computes every calculated field from the row's current inputs.
func (tc *StewardshipAssignment) ComputeAll() *StewardshipAssignment {
	tc.erbComputeCalculations()
	return tc
}

