// =============================================================================
// MESSAGETEMPLATES TABLE
// Approved channel templates projected from the canonical rulebook without becoming a second source of policy meaning.
// =============================================================================

// MessageTemplate represents a row in the MessageTemplates table
type MessageTemplate struct {
	MessageTemplateId string `json:"message_template_id"` // Stored logical identifier for one MessageTemplates row.
	Name *string `json:"name"` // Human-readable calculated display alias for the MessageTemplates row.
	CommunicationPolicy *string `json:"communication_policy"` // Channel policy governing the template.
	Resource *string `json:"resource"` // Template resource.
	SubjectTemplate *string `json:"subject_template"` // Subject template where supported.
	BodyTemplate *string `json:"body_template"` // Body template.
	Locale *string `json:"locale"` // Locale or language tag.
	Status *string `json:"status"` // Draft, Approved, Retired, or Superseded.
	PolicyMaxMessageLength *int `json:"policy_max_message_length"` // Per-segment character limit inherited from the governing channel policy.
	PolicyMaxSegments *int `json:"policy_max_segments"` // Maximum permitted segment count from the governing channel policy.
	BodyTemplateLength *int `json:"body_template_length"` // Character length of the raw template body before variable substitution.
	IsTemplateOverLength *bool `json:"is_template_over_length"` // TRUE when the template body alone already exceeds the single-segment limit before any variables are substituted in.
	ValidApprovalCount *float64 `json:"valid_approval_count"` // Number of properly-authorized approvals on record for this template.
	HasValidApproval *bool `json:"has_valid_approval"` // TRUE when at least one properly-authorized approval exists for this template.
	IsClaimingUnbackedApproval *bool `json:"is_claiming_unbacked_approval"` // TRUE when a template's Status says Approved but no properly-authorized approval record backs it. The phantom-approval witness.
	CurrentBodyHash *string `json:"current_body_hash"` // Digest of the template's current body text, maintained whenever the body is edited.
	LastApprovedBodyHash *string `json:"last_approved_body_hash"` // Digest of the body text as it stood at the most recent valid approval.
	LastValidApproval *string `json:"last_valid_approval"` // The TemplateApprovals id of the approval this template is currently sendable under. Deliberately a raw identifier, not a relationship: TemplateApprovals already points at MessageTemplates, so declaring an FK back would make the two tables mutually dependent and the rulebook is required to stay acyclic. The value is still resolved by INDEX/MATCH in LastApprovedBodyHash.
	HasBodyDrifted *bool `json:"has_body_drifted"` // TRUE when the template body no longer matches what was approved.
	IsSendableUnderApproval *bool `json:"is_sendable_under_approval"` // TRUE only when the template is marked Approved, has a properly-authorized approval, AND its body still matches what was approved.
	DriftedSendCount *float64 `json:"drifted_send_count"` // How many messages went out from this template while it was not validly sendable.
	UnansweredDeliveryCount *float64 `json:"unanswered_delivery_count"` // How many transmitted messages from this template drew no acknowledgement.
	TransmittedDeliveryCount *float64 `json:"transmitted_delivery_count"` // How many deliveries using this template were actually transmitted.
	TemplateDrawsNoResponse *bool `json:"template_draws_no_response"` // TRUE when every transmitted message from this template went unacknowledged.
	LastApprovalAt *string `json:"last_approval_at"` // When this template's currently-governing approval was decided.
	SemanticTypeIri *string `json:"semantic_type_iri"` // Resource class IRI.
	ErbErrors map[string]string `json:"_erb_errors,omitempty"`
	erbAggregates map[string]Value
}

// CalcName computes the Name calculated field
// Human-readable calculated display alias for the MessageTemplates row.
// Formula: ={{CommunicationPolicy}} & " / " & {{Locale}}
func (tc *MessageTemplate) CalcName() *string {
	return toStringPtr(erbConcat(erbText(vStr(tc.CommunicationPolicy)), vS(" / "), erbText(vStr(tc.Locale))))
}

// CalcBodyTemplateLength computes the BodyTemplateLength calculated field
// Character length of the raw template body before variable substitution.
// Formula: =LEN({{BodyTemplate}})
func (tc *MessageTemplate) CalcBodyTemplateLength() *int {
	return toIntPtr(erbInteger(erbLen(vStr(tc.BodyTemplate))))
}

// CalcIsTemplateOverLength computes the IsTemplateOverLength calculated field
// TRUE when the template body alone already exceeds the single-segment limit before any variables are substituted in.
// Formula: ={{BodyTemplateLength}} > {{PolicyMaxMessageLength}}
func (tc *MessageTemplate) CalcIsTemplateOverLength() *bool {
	return toBoolPtr(erbCmp(vInt(tc.BodyTemplateLength), ">", vInt(tc.PolicyMaxMessageLength)))
}

// CalcHasValidApproval computes the HasValidApproval calculated field
// TRUE when at least one properly-authorized approval exists for this template.
// Formula: ={{ValidApprovalCount}} > 0
func (tc *MessageTemplate) CalcHasValidApproval() *bool {
	return toBoolPtr(erbCmp(vNum(tc.ValidApprovalCount), ">", vI(0)))
}

// CalcIsClaimingUnbackedApproval computes the IsClaimingUnbackedApproval calculated field
// TRUE when a template's Status says Approved but no properly-authorized approval record backs it. The phantom-approval witness.
// Formula: =AND({{Status}} = "Approved", NOT({{HasValidApproval}}))
func (tc *MessageTemplate) CalcIsClaimingUnbackedApproval() *bool {
	return toBoolPtr(erbAnd(erbBool3(erbEq(erbNullif(vStr(tc.Status)), vS("Approved"))), erbBool3(erbNot(erbBool3(vBool(tc.HasValidApproval))))))
}

// CalcHasBodyDrifted computes the HasBodyDrifted calculated field
// TRUE when the template body no longer matches what was approved.
// Formula: =AND({{LastApprovedBodyHash}} <> "", {{CurrentBodyHash}} <> {{LastApprovedBodyHash}})
func (tc *MessageTemplate) CalcHasBodyDrifted() *bool {
	return toBoolPtr(erbAnd(erbBool3(erbIsNotBlank(vStr(tc.LastApprovedBodyHash))), erbBool3(erbNe(erbNullif(vStr(tc.CurrentBodyHash)), vStr(tc.LastApprovedBodyHash)))))
}

// CalcIsSendableUnderApproval computes the IsSendableUnderApproval calculated field
// TRUE only when the template is marked Approved, has a properly-authorized approval, AND its body still matches what was approved.
// Formula: =AND({{Status}} = "Approved", AND({{HasValidApproval}}, NOT({{HasBodyDrifted}})))
func (tc *MessageTemplate) CalcIsSendableUnderApproval() *bool {
	return toBoolPtr(erbAnd(erbBool3(erbEq(erbNullif(vStr(tc.Status)), vS("Approved"))), erbBool3(erbAnd(erbBool3(vBool(tc.HasValidApproval)), erbBool3(erbNot(erbBool3(vBool(tc.HasBodyDrifted))))))))
}

// CalcTemplateDrawsNoResponse computes the TemplateDrawsNoResponse calculated field
// TRUE when every transmitted message from this template went unacknowledged.
// Formula: =AND({{TransmittedDeliveryCount}} > 0, {{UnansweredDeliveryCount}} = {{TransmittedDeliveryCount}})
func (tc *MessageTemplate) CalcTemplateDrawsNoResponse() *bool {
	return toBoolPtr(erbAnd(erbBool3(erbCmp(vNum(tc.TransmittedDeliveryCount), ">", vI(0))), erbBool3(erbEq(vNum(tc.UnansweredDeliveryCount), vNum(tc.TransmittedDeliveryCount)))))
}

// erbComputeCalculations computes every calculated field of the row in dependency order.
func (tc *MessageTemplate) erbComputeCalculations() {
	// Level 1
	calcGuard(tc, "name", func() { tc.Name = tc.CalcName() })
	calcGuard(tc, "body_template_length", func() { tc.BodyTemplateLength = tc.CalcBodyTemplateLength() })
	calcGuard(tc, "has_valid_approval", func() { tc.HasValidApproval = tc.CalcHasValidApproval() })
	calcGuard(tc, "has_body_drifted", func() { tc.HasBodyDrifted = tc.CalcHasBodyDrifted() })
	calcGuard(tc, "template_draws_no_response", func() { tc.TemplateDrawsNoResponse = tc.CalcTemplateDrawsNoResponse() })
	// Level 2
	calcGuard(tc, "is_template_over_length", func() { tc.IsTemplateOverLength = tc.CalcIsTemplateOverLength() })
	calcGuard(tc, "is_claiming_unbacked_approval", func() { tc.IsClaimingUnbackedApproval = tc.CalcIsClaimingUnbackedApproval() })
	calcGuard(tc, "is_sendable_under_approval", func() { tc.IsSendableUnderApproval = tc.CalcIsSendableUnderApproval() })
}

// ComputeAll computes every calculated field from the row's current inputs.
func (tc *MessageTemplate) ComputeAll() *MessageTemplate {
	tc.erbComputeCalculations()
	return tc
}

