type TemplateApproval struct {
	TemplateApprovalId string `json:"template_approval_id"` // Stored logical identifier for one TemplateApprovals row.
	Name *string `json:"name"` // Human-readable calculated display alias for the TemplateApprovals row.
	MessageTemplate *string `json:"message_template"` // Template this decision applies to.
	DecidedByAgent *string `json:"decided_by_agent"` // Agent who made the approval decision.
	DecidedInRole *string `json:"decided_in_role"` // Role the agent was acting in when deciding.
	Decision *string `json:"decision"` // Approved, Rejected, or Withdrawn.
	DecidedAt *string `json:"decided_at"` // When the decision was recorded.
	ApprovedBodyHash *string `json:"approved_body_hash"` // Digest of the exact template body that was approved, so later edits are detectable.
	Notes *string `json:"notes"` // Approver's rationale or conditions.
	IsApprovalDecision *bool `json:"is_approval_decision"` // TRUE when this decision row is an approval rather than a rejection or withdrawal.
	TemplatePolicy *string `json:"template_policy"` // The communication policy governing the template being approved.
	RequiredApprovalRole *string `json:"required_approval_role"` // The role the governing policy designates as approver -- communications-manager for both current policies.
	IsDecidedByRequiredRole *bool `json:"is_decided_by_required_role"` // TRUE when the approving role matches the role the policy designates.
	ValidApprovalTemplateKey *string `json:"valid_approval_template_key"` // Carries the template id only on approvals made by the correct role; empty string otherwise.
	SemanticTypeIri *string `json:"semantic_type_iri"` // Extension IRI; template approval events are not a PKO 2.0.0 native class.
	ErbErrors map[string]string `json:"_erb_errors,omitempty"`
	erbAggregates map[string]Value
}

// CalcName computes the Name calculated field
// Human-readable calculated display alias for the TemplateApprovals row.
// Formula: ={{MessageTemplate}} & " / " & {{Decision}} & " / " & {{DecidedAt}}
func (tc *TemplateApproval) CalcName() *string {
	return toStringPtr(erbConcat(erbText(vStr(tc.MessageTemplate)), vS(" / "), erbText(vStr(tc.Decision)), vS(" / "), erbDatetimeText(vStr(tc.DecidedAt))))
}

// CalcIsApprovalDecision computes the IsApprovalDecision calculated field
// TRUE when this decision row is an approval rather than a rejection or withdrawal.
// Formula: ={{Decision}} = "Approved"
func (tc *TemplateApproval) CalcIsApprovalDecision() *bool {
	return toBoolPtr(erbEq(erbNullif(vStr(tc.Decision)), vS("Approved")))
}

// CalcIsDecidedByRequiredRole computes the IsDecidedByRequiredRole calculated field
// TRUE when the approving role matches the role the policy designates.
// Formula: ={{DecidedInRole}} = {{RequiredApprovalRole}}
func (tc *TemplateApproval) CalcIsDecidedByRequiredRole() *bool {
	return toBoolPtr(erbEq(erbNullif(vStr(tc.DecidedInRole)), vStr(tc.RequiredApprovalRole)))
}

// CalcValidApprovalTemplateKey computes the ValidApprovalTemplateKey calculated field
// Carries the template id only on approvals made by the correct role; empty string otherwise.
// Formula: =IF(AND({{IsApprovalDecision}}, {{IsDecidedByRequiredRole}}), {{MessageTemplate}}, "")
func (tc *TemplateApproval) CalcValidApprovalTemplateKey() *string {
	return toStringPtr(erbIf(erbBool3(erbAnd(erbBool3(vBool(tc.IsApprovalDecision)), erbBool3(vBool(tc.IsDecidedByRequiredRole)))), func() Value { return vStr(tc.MessageTemplate) }, func() Value { return vS("") }))
}

// erbComputeCalculations computes every calculated field of the row in dependency order.
func (tc *TemplateApproval) erbComputeCalculations() {
	// Level 1
	calcGuard(tc, "name", func() { tc.Name = tc.CalcName() })
	calcGuard(tc, "is_approval_decision", func() { tc.IsApprovalDecision = tc.CalcIsApprovalDecision() })
	calcGuard(tc, "is_decided_by_required_role", func() { tc.IsDecidedByRequiredRole = tc.CalcIsDecidedByRequiredRole() })
	// Level 2
	calcGuard(tc, "valid_approval_template_key", func() { tc.ValidApprovalTemplateKey = tc.CalcValidApprovalTemplateKey() })
}

// ComputeAll computes every calculated field from the row's current inputs.
func (tc *TemplateApproval) ComputeAll() *TemplateApproval {
	tc.erbComputeCalculations()
	return tc
}

