// CalcIsCurrentlyBinding computes the IsCurrentlyBinding calculated field
// TRUE when this boundary is approved and inside its valid-time window right now.
// Formula: =AND({{Status}} = "Approved", {{ValidFrom}} <= {{AsOfInstant}}, OR({{ValidTo}} = "", {{ValidTo}} > {{AsOfInstant}}))
func (tc *AuthorityBoundarie) CalcIsCurrentlyBinding() *bool {
	return toBoolPtr(erbAnd(erbBool3(erbEq(erbNullif(vStr(tc.Status)), vS("Approved"))), erbBool3(erbCmp(erbNullif(vStr(tc.ValidFrom)), "<=", vStr(tc.AsOfInstant))), erbBool3(erbOr(erbBool3(erbIsBlank(vStr(tc.ValidTo))), erbBool3(erbCmp(erbNullif(vStr(tc.ValidTo)), ">", vStr(tc.AsOfInstant)))))))
}

// CalcStepWhenBinding computes the StepWhenBinding calculated field
// Echoes the step id when this boundary is currently binding, blank otherwise.
// Formula: =IF({{IsCurrentlyBinding}}, {{Step}}, "")
func (tc *AuthorityBoundarie) CalcStepWhenBinding() *string {
	return toStringPtr(erbIf(erbBool3(vBool(tc.IsCurrentlyBinding)), func() Value { return vStr(tc.Step) }, func() Value { return vS("") }))
}

// CalcBoundaryMatchKey computes the BoundaryMatchKey calculated field
// Composite key of step, forbidden agent kind, and forbidden decision kind.
// Formula: ={{Step}} & "|" & {{ForbiddenAgentKind}} & "|" & {{ForbiddenDecisionKind}}
