// =============================================================================
// PROCESSMININGRUNS TABLE
// One conformance-checking run of a mined event log against a documented procedure version — a third kind of evidence, distinct from an elicitation session (someone's account) or a knowledge fragment (a claim): what the system of record actually did, discovered by process mining rather than told to us.
// =============================================================================

// ProcessMiningRun represents a row in the ProcessMiningRuns table
type ProcessMiningRun struct {
	ProcessMiningRunId string `json:"process_mining_run_id"` // Stored logical identifier for one ProcessMiningRuns row.
	Name *string `json:"name"` // Human-readable calculated display alias for the ProcessMiningRuns row.
	ProcedureVersion *string `json:"procedure_version"` // Procedure version this mined event log is checked against.
	EventLogSource *string `json:"event_log_source"` // System or log the event log was extracted from (e.g. an ERP audit log).
	MinedAt *string `json:"mined_at"` // When this mining/conformance-checking run was performed.
	DiscoveredVariantCount *int `json:"discovered_variant_count"` // Distinct process variants discovered in the mined event log.
	ConformingVariantCount *int `json:"conforming_variant_count"` // How many of the discovered variants exactly match a documented path through StepTransitions.
	DeviationDescription *string `json:"deviation_description"` // Narrative of the most significant discovered deviation, if any.
	EvaluationContext *string `json:"evaluation_context"` // The evaluation context this row's time-dependent witnesses are judged under.
	AsOfInstant *string `json:"as_of_instant"` // The evaluation instant this row's time-dependent witnesses are judged under.
	ConformanceRate *float64 `json:"conformance_rate"` // Share of discovered variants that conform to the documented procedure.
	IsConformant *bool `json:"is_conformant"` // TRUE when at least 80% of what actually happened matches what was documented.
	HasMajorDriftFromDocumentation *bool `json:"has_major_drift_from_documentation"` // TRUE when less than half of what actually happened matches what was documented.
	DaysSinceMined *int `json:"days_since_mined"` // Days elapsed since this event log was mined.
	IsStaleMiningEvidence *bool `json:"is_stale_mining_evidence"` // TRUE when this mining evidence is more than 180 days old.
	ProcedureVersionIsLive *bool `json:"procedure_version_is_live"` // Whether the procedure version this run was checked against is currently live.
	IsDriftOnLiveVersion *bool `json:"is_drift_on_live_version"` // TRUE when a major, real, mined deviation exists against a procedure version people are actually executing right now.
	DriftedMiningRunKey *string `json:"drifted_mining_run_key"` // Composite-key echo: this run's procedure version when the run drifted on a live version, else blank.
	SemanticTypeIri *string `json:"semantic_type_iri"` // Extension class IRI.
	ErbErrors map[string]string `json:"_erb_errors,omitempty"`
	erbAggregates map[string]Value
}

// CalcName computes the Name calculated field
// Human-readable calculated display alias for the ProcessMiningRuns row.
// Formula: ={{EventLogSource}} & " / " & {{MinedAt}}
func (tc *ProcessMiningRun) CalcName() *string {
	return toStringPtr(erbConcat(erbText(vStr(tc.EventLogSource)), vS(" / "), erbDatetimeText(vStr(tc.MinedAt))))
}

// CalcConformanceRate computes the ConformanceRate calculated field
// Share of discovered variants that conform to the documented procedure.
// Formula: =IF({{DiscoveredVariantCount}} = 0, 0, {{ConformingVariantCount}} / {{DiscoveredVariantCount}})
func (tc *ProcessMiningRun) CalcConformanceRate() *float64 {
	return toFloatPtr(erbIf(erbBool3(erbEq(erbNullif(vInt(tc.DiscoveredVariantCount)), vI(0))), func() Value { return vI(0) }, func() Value { return erbDiv(vInt(tc.ConformingVariantCount), vInt(tc.DiscoveredVariantCount)) }))
}

// CalcIsConformant computes the IsConformant calculated field
// TRUE when at least 80% of what actually happened matches what was documented.
// Formula: ={{ConformanceRate}} >= 0.8
func (tc *ProcessMiningRun) CalcIsConformant() *bool {
	return toBoolPtr(erbCmp(vNum(tc.ConformanceRate), ">=", vF(0.8)))
}

// CalcHasMajorDriftFromDocumentation computes the HasMajorDriftFromDocumentation calculated field
// TRUE when less than half of what actually happened matches what was documented.
// Formula: ={{ConformanceRate}} < 0.5
func (tc *ProcessMiningRun) CalcHasMajorDriftFromDocumentation() *bool {
	return toBoolPtr(erbCmp(vNum(tc.ConformanceRate), "<", vF(0.5)))
}

// CalcDaysSinceMined computes the DaysSinceMined calculated field
// Days elapsed since this event log was mined.
// Formula: =DATETIME_DIFF({{AsOfInstant}}, {{MinedAt}}, "days")
func (tc *ProcessMiningRun) CalcDaysSinceMined() *int {
	return toIntPtr(erbInteger(erbDatetimeDiff(vStr(tc.AsOfInstant), vStr(tc.MinedAt), vS("days"))))
}

// CalcIsStaleMiningEvidence computes the IsStaleMiningEvidence calculated field
// TRUE when this mining evidence is more than 180 days old.
// Formula: ={{DaysSinceMined}} > 180
func (tc *ProcessMiningRun) CalcIsStaleMiningEvidence() *bool {
	return toBoolPtr(erbCmp(vInt(tc.DaysSinceMined), ">", vI(180)))
}

// CalcIsDriftOnLiveVersion computes the IsDriftOnLiveVersion calculated field
// TRUE when a major, real, mined deviation exists against a procedure version people are actually executing right now.
// Formula: =AND({{HasMajorDriftFromDocumentation}}, {{ProcedureVersionIsLive}})
func (tc *ProcessMiningRun) CalcIsDriftOnLiveVersion() *bool {
	return toBoolPtr(erbAnd(erbBool3(vBool(tc.HasMajorDriftFromDocumentation)), erbBool3(vBool(tc.ProcedureVersionIsLive))))
}

// CalcDriftedMiningRunKey computes the DriftedMiningRunKey calculated field
// Composite-key echo: this run's procedure version when the run drifted on a live version, else blank.
// Formula: =IF({{IsDriftOnLiveVersion}}, {{ProcedureVersion}}, "")
func (tc *ProcessMiningRun) CalcDriftedMiningRunKey() *string {
	return toStringPtr(erbIf(erbBool3(vBool(tc.IsDriftOnLiveVersion)), func() Value { return vStr(tc.ProcedureVersion) }, func() Value { return vS("") }))
}

// erbComputeCalculations computes every calculated field of the row in dependency order.
func (tc *ProcessMiningRun) erbComputeCalculations() {
	// Level 1
	calcGuard(tc, "name", func() { tc.Name = tc.CalcName() })
	calcGuard(tc, "conformance_rate", func() { tc.ConformanceRate = tc.CalcConformanceRate() })
	calcGuard(tc, "days_since_mined", func() { tc.DaysSinceMined = tc.CalcDaysSinceMined() })
	// Level 2
	calcGuard(tc, "is_conformant", func() { tc.IsConformant = tc.CalcIsConformant() })
	calcGuard(tc, "has_major_drift_from_documentation", func() { tc.HasMajorDriftFromDocumentation = tc.CalcHasMajorDriftFromDocumentation() })
	calcGuard(tc, "is_stale_mining_evidence", func() { tc.IsStaleMiningEvidence = tc.CalcIsStaleMiningEvidence() })
	// Level 3
	calcGuard(tc, "is_drift_on_live_version", func() { tc.IsDriftOnLiveVersion = tc.CalcIsDriftOnLiveVersion() })
	// Level 4
	calcGuard(tc, "drifted_mining_run_key", func() { tc.DriftedMiningRunKey = tc.CalcDriftedMiningRunKey() })
}

